def get_difficulty(stats_dict=None):
    if stats_dict and "difficulty" in stats_dict:
        diff = stats_dict["difficulty"]
        if diff in DIFFICULTY:
            return DIFFICULTY[diff]
    return DIFFICULTY["normal"]

# ============================================================
#  ITEM QUALITY SUFFIXES
# ============================================================
QUALITY_SUFFIXES = {
    "cracked": {"atk_mod": 0.7, "def_mod": 0.7, "cost_mod": 0.5, "color": "dim red"},
    "worn": {"atk_mod": 0.85, "def_mod": 0.85, "cost_mod": 0.75, "color": "dim white"},
    "standard": {"atk_mod": 1.0, "def_mod": 1.0, "cost_mod": 1.0, "color": "white"},
    "polished": {"atk_mod": 1.15, "def_mod": 1.15, "cost_mod": 1.25, "color": "green"},
    "superior": {"atk_mod": 1.3, "def_mod": 1.3, "cost_mod": 1.5, "color": "cyan"},
    "masterwork": {"atk_mod": 1.5, "def_mod": 1.5, "cost_mod": 2.0, "color": "blue"},
    "legendary": {"atk_mod": 2.0, "def_mod": 2.0, "cost_mod": 3.0, "color": "yellow"},
}

def apply_quality(item, quality="standard"):
    q = QUALITY_SUFFIXES.get(quality, QUALITY_SUFFIXES["standard"])
    if quality == "standard":
        return item
    modified = dict(item)
    name = modified.get("Name", "Item")
    modified["Name"] = f"{quality.title()} {name}"
    if "ATK" in modified:
        modified["ATK"] = round(modified["ATK"] * q["atk_mod"], 1)
    if "DEF" in modified:
        modified["DEF"] = round(modified["DEF"] * q["def_mod"], 1)
    if "Cost" in modified:
        modified["Cost"] = int(modified["Cost"] * q["cost_mod"])
    return modified

def random_quality():
    roll = random.randint(1, 100)
    if roll <= 30: return "cracked"
    if roll <= 55: return "worn"
    if roll <= 75: return "standard"
    if roll <= 87: return "polished"
    if roll <= 95: return "superior"
    if roll <= 99: return "masterwork"
    return "legendary"

