CAMP_FLAVOR = [
    "You set up camp and rest for the night. The stars wheel overhead as you drift to sleep.",
    "You find a sheltered spot under an overhang and build a small fire. The warmth is soothing.",
    "You rest by a crystal-clear stream, letting the sound of flowing water wash away your fatigue.",
    "An abandoned watchtower provides shelter. You bar the door and rest, one eye on the window.",
    "You find a peaceful glade where fireflies dance. The magic of the place restores your spirit.",
]

def rest_at_camp(stats_dict, heal_percent=0.5):
    flavor = random.choice(CAMP_FLAVOR)
    console.print(f"[dim italic]{flavor}[/dim italic]")
    time.sleep(0.5)
    heal = int(stats_dict.get("Max HP", stats_dict.get("HP", 1000)) * heal_percent)
    stats_dict["HP"] = min(stats_dict.get("Max HP", stats_dict["HP"]), stats_dict.get("HP", 0) + heal)
    event(f"Rested. +{heal} HP ({stats_dict['HP']}/{stats_dict.get('Max HP', stats_dict['HP'])}).", "heal")
    time.sleep(0.3)
# ============================================================
#  RANK / TITLE SYSTEM
# ============================================================
RANK_TITLES = [
    (0, "Fledgling"),
    (5, "Adventurer"),
    (10, "Seasoned Explorer"),
    (20, "Hero of the Realm"),
    (35, "Elite Champion"),
    (50, "Master Warrior"),
    (75, "Legendary Guardian"),
    (100, "Mythic Conqueror"),
]

def get_player_title(lvl: int) -> str:
    title = "Wanderer"
    for req, t in reversed(RANK_TITLES):
        if lvl >= req:
            title = t
            break
    return title

def get_rank_progress(lvl: int) -> Tuple[str, str, float]:
    current_title = get_player_title(lvl)
    next_req = None
    next_title = None
    for req, t in RANK_TITLES:
        if lvl < req:
            next_req = req
            next_title = t
            break
    if next_req:
        progress = (lvl - max(r for r, _ in RANK_TITLES if r <= lvl)) / (next_req - max(r for r, _ in RANK_TITLES if r <= lvl))
    else:
        progress = 1.0
    return current_title, next_title or "MAX", progress

