# ============================================================
#  ENCYCLOPEDIA VIEWER
# ============================================================
def bestiary_viewer() -> None:
    screen_title("📖 BESTIARY", "Knowledge of the foes you face")
    names = list(BESTIARY.keys())
    page_size = 3
    page = 0
    while True:
        clear()
        section("BESTIARY")
        start_idx = page * page_size
        end_idx = min(start_idx + page_size, len(names))
        for i in range(start_idx, end_idx):
            name = names[i]
            entry = BESTIARY[name]
            console.print(f"  [bold cyan]{name}[/bold cyan]  [dim](Danger: {entry['danger']})[/dim]")
            console.print(f"    [italic]{entry['lore']}[/italic]")
            console.print(f"    [dim]Habitat: {entry['habitat']}[/dim]")
            console.print(f"    [dim green]Tip: {entry['tips']}[/dim green]")
            console.print()
        console.print(f"  [dim]Page {page + 1}/{(len(names) - 1)//page_size + 1}[/dim]")
        console.print()
        console.print("  [bold cyan]1.[/bold cyan]  Next page")
        console.print("  [bold cyan]2.[/bold cyan]  Previous page")
        console.print("  [bold cyan]3.[/bold cyan]  Return")
        choice = int_prompt("Choice: ")
        if choice == 1 and end_idx < len(names):
            page += 1
        elif choice == 2 and page > 0:
            page -= 1
        elif choice == 3:
            break

# ============================================================
#  ZONE EXPLORATION EXTRA
# ============================================================
def explore_zone_lore(zone_key: str) -> None:
    lore = ZONE_LORE.get(zone_key)
    if not lore:
        return
    screen_title(lore["title"], "Lore & History")
    dialogue(lore["history"], "narrator", 0.03)
    time.sleep(0.5)
    clear()
    info_panel("Points of Interest", "\n".join(f"  • {p}" for p in lore["points_of_interest"]))
    time.sleep(0.5)
    console.print()
    voice_say(f"Rumor: {lore['secrets']}", "whisper")
    time.sleep(0.5)
    console.input("[dim]Press Enter to continue...[/dim]")
    clear()

# ============================================================
#  ITEM COMPARISON HELPER
# ============================================================
def compare_equipment(current: Dict[str, Any], new: Dict[str, Any]) -> str:
    """Compare two equipment dicts and return a color-coded comparison summary."""
    stat_keys = ["ATK", "DEF", "SP", "Crit", "DUR", "MAX DUR"]
    diffs = []
    for key in stat_keys:
        old_val = current.get(key, 0)
        new_val = new.get(key, 0)
        if old_val != new_val:
            diff = new_val - old_val
            if diff > 0:
                diffs.append(f"[bold green]{key}: {old_val} → {new_val} (+{diff})[/bold green]")
            else:
                diffs.append(f"[bold red]{key}: {old_val} → {new_val} ({diff})[/bold red]")
    if not diffs:
        return "[dim]Identical stats[/dim]"
    return "\n".join(diffs)
