def get_random_flavor(category: str, subcategory: str = None) -> str:
    if subcategory:
        entries = COMBAT_FLAVOR.get(subcategory, [])
    else:
        entries = NPC_GREETINGS.get(category, [])
    return random.choice(entries) if entries else ""

