def roll_loot(zone: str) -> Dict[str, Any]:
    table = loot_tables.get(zone, loot_tables["crimson_fields"])
    roll = random.randint(1, 100)
    if roll <= 50:
        return random.choice(table["common"])
    elif roll <= 85:
        return random.choice(table["uncommon"])
    else:
        return random.choice(table["rare"])

