def get_enemy_variant(base_name: str) -> Tuple[str, Dict[str, float]]:
    entry = enemy_variants.get(base_name)
    if not entry:
        return base_name, {}
    idx = random.randint(0, len(entry["variants"]) - 1)
    return entry["variants"][idx], entry["mods"][idx]

