def get_codex_category(cat: str) -> List[Tuple[str, str]]:
    data = CODEX.get(cat)
    if not data:
        return []
    return data.get("entries", [])

def get_codex_title(cat: str) -> str:
    data = CODEX.get(cat)
    if not data:
        return "Unknown"
    return data.get("title", "Unknown")

# ============================================================
#  CODEX VIEWER
# ============================================================
def codex_viewer() -> None:
    cats = list(CODEX.keys())
    while True:
        screen_title("📖 THE CODEX", "Lore, history, and secrets of the realm")
        for i, cat in enumerate(cats, 1):
            console.print(f"  [bold cyan]{i}.[/bold cyan] [bold white]{get_codex_title(cat)}[/bold white]")
        console.print(f"  [bold cyan]{len(cats) + 1}.[/bold cyan] [bold white]Return[/bold white]")
        choice = int_prompt("Choose: ")
        if 1 <= choice <= len(cats):
            cat = cats[choice - 1]
            clear()
            section(get_codex_title(cat).upper())
            entries = get_codex_category(cat)
            for title, body in entries:
                console.print(f"  [bold yellow]{title}[/bold yellow]")
                dialogue(body, "narrator", 0.02)
                console.print()
                time.sleep(0.1)
            console.input("[dim]Press Enter to continue...[/dim]")
            clear()
        else:
            break

