def maybe_spawn_elite(pool_name: str, base_pool: Dict) -> Tuple[str, Dict]:
    if random.randint(1, 100) <= ADVENTURE_ELITE_CHANCE:
        elites_pool = elite_monsters if pool_name == "monsters" else elite_monsters
        name = random.choice(list(elites_pool.keys()))
        return name, elites_pool[name]
    name = random.choice(list(base_pool.keys()))
    return name, base_pool[name]

