def roll_rarity():
    roll = random.randint(1, 100)
    cum = 0
    for r, d in loot_rarities.items():
        cum += d["weight"]
        if roll <= cum: return r
    return "common"
def rarity_color(item):
    c = item.get("Cost", 0)
    if c > 100000: return "bold yellow"
    if c > 50000: return "bold magenta"
    if c > 20000: return "bold blue"
    if c > 10000: return "bold green"
    return "bold white"
def format_item_name(item):
    return f"[{rarity_color(item)}]{item.get('Name', 'Unknown')}[/{rarity_color(item)}]"

# ============================================================
#  ITEM COMPARISON
# ============================================================
def stat_diff(old_val, new_val, label):
    if old_val == new_val: return ""
    diff = new_val - old_val
    c = "green" if diff > 0 else "red"
    return f"  {label}: [bold]{old_val}[/bold] -> [bold {c}]{new_val} ({'+' if diff > 0 else ''}{diff:.1f})[/bold {c}]"
def compare_items(old_item, new_item):
    lines = []
    for key in ["ATK", "DEF", "SP", "Crit", "DUR", "MAX DUR"]:
        if key in old_item or key in new_item:
            s = stat_diff(old_item.get(key, 0), new_item.get(key, 0), key)
            if s: lines.append(s)
    return lines

