def start(item, action, lower, upper):
    duration = random.uniform(lower, upper)
    loading_bar(f"{action} {item}...", duration)
def timer_loop(seconds):
    global tournament_active
    start = time.time()
    while time.time() - start < seconds:
        time.sleep(1)
    tournament_active[0] = False
    console.print("\n🏆 Tournament Over!")

enchant_progress = {
    "start_time": None,
    "duration": None,
    "done": False
}
def enchantment_worker(duration):
    enchant_progress["start_time"] = time.time()
    enchant_progress["duration"] = duration
    enchant_progress["done"] = False
    while True:
        elapsed = time.time() - enchant_progress["start_time"]
        if elapsed >= duration:
            enchant_progress["done"] = True
            break
        time.sleep(0.2)
def start_enchant(duration):
    threading.Thread(target=enchantment_worker, args=(duration,), daemon=True).start()
    console.print("✨ Enchantment begun! Do your thing while the crystal does its magic... 🧙‍♀️💠")
def check_enchantment():
    if enchant_progress["start_time"] is None:
        console.print("🧐 Nothing is being enchanted right now!")
        return

    console.print("📡 Enchantment progress ... (press ENTER to return to town 🏙️)")

    while True:
        if enchant_progress["done"]:
            return 1
        else:
            elapsed = time.time() - enchant_progress["start_time"]
            remaining = enchant_progress["duration"] - elapsed
            percent = int((elapsed / enchant_progress["duration"]) * 100)
            console.print(f"\r🧪 Enchanting... {percent}% done | {remaining:.1f}s left", end="", flush=True)
            time.sleep(0.00001)
        if sys.stdin in select.select([sys.stdin], [], [], 0)[0]:
            console.input()  
            console.print("\n🚪 You leave the armory and head back to town.")
            break

def load_players(filename="players.json"):
    if os.path.exists(filename):
            if os.path.getsize(filename) == 0:
                with open(filename, "w") as file:
                    json.dump({}, file)
            with open(filename, "r") as file:
                return json.load(file)
    else:
        return {}
def save_players(players, filename="players.json"):
    with open(filename, "w") as file:
        json.dump(players, file, indent=4)

from settings import SETTINGS
from rich.prompt import Prompt
from ui import clear, type, fasttype, chat, event, menu_panel, info_panel, section, stats_table, equip_card, inventory_table, loading_bar, console, zone_header, small_title, announcement, combat_panel, int_prompt

def run_arena_style_combat(stats: Dict[str, Any], foe: Dict[str, Any]) -> Tuple[bool, int]:
    return _arena_combat_engine(stats, foe, type, clear, fasttype)

def grant_exp(stats: Dict[str, Any], amount: float) -> None:
    stats["EXP"] = stats.get("EXP", 0) + amount
    while stats["EXP"] >= stats["Max EXP"]:
        over = stats["EXP"] - stats["Max EXP"]
        stats["Lvl"] += 1
        stats["Max EXP"] += 20
        stats["EXP"] = over

def _apply_arena_rewards(stats: Dict[str, Any], won: bool, foe_lvl: int, turns: int) -> None:
    if not won:
        type("You limp away from the arena...")
        stats["arena_losses"] = stats.get("arena_losses", 0) + 1
        modify_faction_standing("Iron Legion", -1, stats)
        time.sleep(0.8)
        clear()
        return
    diff = SETTINGS.get_difficulty()
    base_exp = max(25, foe_lvl * 6)
    speed_bonus = max(0, int(35 - turns * 2))
    total_exp = int((base_exp + speed_bonus) * diff.get("exp_mult", 1.0))
    grant_exp(stats, float(total_exp))
    gold_gain = int((foe_lvl * 22 + speed_bonus * 4) * diff.get("gold_mult", 1.0))
    stats["Gold"] += gold_gain
    stats["Reputation"] = stats.get("Reputation", 0) + 1
    stats["arena_wins"] = stats.get("arena_wins", 0) + 1
    modify_faction_standing("Iron Legion", 2, stats)
    type(f"Victory spoils: +{total_exp} EXP, +{gold_gain} gold, +1 reputation.")
    time.sleep(0.9)
    clear()

def build_duel_foe_from_key(enemy_players: Dict[Any, Dict[str, Any]], p_key: Any) -> Dict[str, Any]:
    """Build combat foe dict compatible with arena_combat from an arena challenger entry."""
    foe_lvl_roll = max(1, int(enemy_players[p_key]["lvl"]))
    wroll = random.randint(1, 100)
    if wroll <= 70 - foe_lvl_roll:
        foe_weapon = random.choice(swords)
    else:
        foe_weapon = random.choice(elite_swords)
    arena_shields = [
        {"Name": "Reinforced Bark Shield", "DEF": 1.5, "SP": 0.8, "MAX DUR": 900, "DUR": 900, "Cost": 7000, "Class": "Shield"},
        {"Name": "Rusty Steel Shield", "DEF": 1.3, "SP": 0.8, "MAX DUR": 1000, "DUR": 1000, "Cost": 5000, "Class": "Shield"},
        {"Name": "Chainmail Shield", "DEF": 1.2, "SP": 0.9, "MAX DUR": 850, "DUR": 850, "Cost": 5000, "Class": "Shield"},
        {"Name": "Reinforced Leather Shield", "DEF": 1.5, "SP": 1, "MAX DUR": 1150, "DUR": 1150, "Cost": 9000, "Class": "Shield"},
        {"Name": "Wooden Shield", "DEF": 2, "SP": 1, "MAX DUR": 60, "DUR": 60, "Cost": 14000, "Class": "Shield"},
        {"Name": "Rusted Steel Shield", "DEF": 1.3, "SP": 0.8, "MAX DUR": 1000, "DUR": 1000, "Cost": 4000, "Class": "Shield"},
        {"Name": "Leather Shield", "DEF": 1.5, "SP": 1, "MAX DUR": 1150, "DUR": 1150, "Cost": 8000, "Class": "Shield"}
    ]
    foe_shield = random.choice(arena_shields)
    chestplate_roll = random.randint(1, 100)
    if chestplate_roll <= 70 - foe_lvl_roll:
        foe_chest = random.choice(chestplates)
    else:
        foe_chest = None
    helmet_roll = random.randint(1, 100)
    if helmet_roll <= 70 - foe_lvl_roll:
        foe_helmet = random.choice(helmets)
    else:
        foe_helmet = None
    legging_roll = random.randint(1, 100)
    if legging_roll <= 70 - foe_lvl_roll:
        foe_legging = random.choice(leggings)
    else:
        foe_legging = None
    boot_roll = random.randint(1, 100)
    if boot_roll <= 70 - foe_lvl_roll:
        foe_boot = random.choice(boots)
    else:
        foe_boot = None
    enemyhp = 1700
    enemystr = 150
    enemydef = 70
    enemycrit = 7
    enemysp = 20
    if foe_lvl_roll <= 0:
        buff_times = 1
    else:
        buff_times = foe_lvl_roll
    for _ in range(buff_times):
        bt = random.choice(["HP", "ATK", "DEF", "SP", "CRIT"]).lower()
        if bt == "hp":
            enemyhp += 200
        elif bt == "atk":
            enemystr += 10
        elif bt == "def":
            enemydef += 20
        elif bt == "sp":
            enemysp += 2.5
        elif bt == "crit":
            enemycrit += 0.5
    return {
        "name": enemy_players[p_key]["name"],
        "lvl": enemy_players[p_key]["lvl"],
        "enemyhp": enemyhp,
        "enemystr": enemystr,
        "enemydef": enemydef,
        "enemycrit": enemycrit,
        "enemysp": enemysp,
        "weapon": foe_weapon,
        "shield": foe_shield,
        "helmet": foe_helmet,
        "chestplate": foe_chest,
        "legging": foe_legging,
        "boot": foe_boot,
    }

def roll_random_arena_npc(player_stats: Dict[str, Any]) -> Dict[str, Any]:
    rank = random.randint(player_stats["Rank"] - 1000, player_stats["Rank"] + 1000)
    hi = random.choice(["Yes", "No"])
    prefix = random.choice(prefixes)
    middle = random.choice(middles)
    suffix = random.choice(suffixes)
    if hi == "Yes":
        nid = random.randint(0, 999)
        player_name = f"{prefix}{middle}{suffix}_{nid}"
    else:
        player_name = f"{prefix}{middle} {suffix}"
    lvl = random.randint(max(1, player_stats["Lvl"] - 10), player_stats["Lvl"] + 10)
    challenger = {0: {"name": player_name, "rank": rank, "lvl": lvl}}
    return build_duel_foe_from_key(challenger, 0)

def foe_from_boss_entry(player_stats: Dict[str, Any], boss_title: str, bdata: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "name": boss_title,
        "lvl": max(1, player_stats["Lvl"]),
        "enemyhp": bdata["HP"],
        "enemystr": bdata["ATK"],
        "enemydef": bdata["DEF"],
        "enemycrit": bdata["Crit"],
        "enemysp": bdata["SP"],
        "weapon": copy.deepcopy(bdata["Weapon"]),
        "shield": copy.deepcopy(bdata["Left Hand"]),
        "helmet": copy.deepcopy(bdata["Helmet"]),
        "chestplate": copy.deepcopy(bdata["Chestplate"]),
        "legging": copy.deepcopy(bdata["Leggings"]),
        "boot": copy.deepcopy(bdata["Boots"]),
    }

def _ensure_equip_fields(item: Dict[str, Any]) -> Dict[str, Any]:
    if "MAX DUR" not in item:
        item["MAX DUR"] = 500
    if "DUR" not in item:
        item["DUR"] = 500
    if "Class" not in item:
        item["Class"] = "Weapon"
    return item

def foe_from_mob_entry(player_stats: Dict[str, Any], mob_name: str, mdata: Dict[str, Any]) -> Dict[str, Any]:
    lvl = max(1, player_stats.get("Lvl", 1))
    return {
        "name": mob_name,
        "lvl": lvl,
        "enemyhp": mdata["HP"] + (lvl * 50),
        "enemystr": mdata["ATK"] + (lvl * 5),
        "enemydef": mdata["DEF"] + (lvl * 3),
        "enemycrit": mdata.get("Crit", 5),
        "enemysp": mdata.get("SP", 10),
        "weapon": _ensure_equip_fields(copy.deepcopy(mdata.get("Weapon", {"Name": "Claws", "ATK": 1, "SP": 1, "Crit": 1}))),
        "shield": copy.deepcopy(mdata.get("Left Hand", {})),
        "helmet": copy.deepcopy(mdata.get("Helmet", {})),
        "chestplate": copy.deepcopy(mdata.get("Chestplate", {})),
        "legging": copy.deepcopy(mdata.get("Leggings", {})),
        "boot": copy.deepcopy(mdata.get("Boots", {})),
    }

def dungeon_adventure(stats: Dict[str, Any]) -> None:
    themes = list(DUNGEON_THEMES.keys())
    screen_title("🏰 DUNGEON DIVE", "Descend into a procedural dungeon")
    console.print("Choose a dungeon theme:")
    for i, t in enumerate(themes, 1):
        theme = DUNGEON_THEMES[t]
        console.print(f"  [bold cyan]{i}.[/bold cyan] [bold white]{theme['name']}[/bold white] [dim]- {theme['desc']}[/dim]")
    console.print(f"  [bold cyan]{len(themes) + 1}.[/bold cyan] [bold white]Back[/bold white]")
    choice = int_prompt("Choose: ")
    clear()
    if 1 <= choice <= len(themes):
        theme_key = themes[choice - 1]
        dungeon = generate_dungeon(theme_key, stats.get("Lvl", 1))
        screen_title(f"⚔ {dungeon['name']} ⚔", dungeon['desc'])
        dialogue("You descend into the depths...", "narrator", 0.03)
        time.sleep(0.3)
        weather = roll_weather(dungeon.get("theme_key", "rotfang"))
        describe_weather_now(weather)
        diff = SETTINGS.get_difficulty()
        for floor_idx, floor in enumerate(dungeon["floors"]):
            describe_dungeon_floor(floor)
            time.sleep(0.2)
            if random.random() < floor.get("trap_chance", 0.1):
                event("A trap! You take some damage.", "danger")
                stats["HP"] = max(0, stats.get("HP", 0) - int(stats.get("Max HP", 1000) * 0.1))
            for e in range(floor.get("enemy_count", 1)):
                enemy_name = random.choice(dungeon["enemies"])
                e_pool = {enemy_name: soldiers.get(enemy_name, monsters.get(enemy_name, list(monsters.values())[0]))}
                if enemy_name in boss:
                    e_pool = {enemy_name: boss[enemy_name]}
                foe_data = e_pool[enemy_name]
                foe = foe_from_mob_entry(stats, enemy_name, foe_data)
                foe["ATK"] = int(foe["ATK"] * diff.get("dmg_mult", 1.0))
                foe["HP"] = int(foe["HP"] * diff.get("hp_mult", 1.0))
                battle_intro(enemy_name)
                won, _ = run_arena_style_combat(stats, foe)
                if not won:
                    event("Defeated in the dungeon!", "death")
                    gold_loss = int(stats.get("Gold", 0) * 0.2)
                    stats["Gold"] = max(0, stats.get("Gold", 0) - gold_loss)
                    return
                exp_g = int(50 * diff.get("exp_mult", 1.0) * (floor_idx + 1))
                gold_g = int(200 * diff.get("gold_mult", 1.0) * (floor_idx + 1))
                grant_exp(stats, exp_g)
                stats["Gold"] = stats.get("Gold", 0) + gold_g
                event(f"Floor cleared! +{exp_g} EXP, +{gold_g} gold", "loot")
                if random.random() < floor.get("treasure_chance", 0.2):
                    roll_treasure_chest(stats, floor_idx + 1)
                time.sleep(0.2)
            if floor_idx < len(dungeon["floors"]) - 1:
                enhanced_rest_at_camp(stats, 0.2)
        final_boss_name = dungeon["boss"]
        boss_data = boss.get(final_boss_name, list(boss.values())[0])
        b_foe = foe_from_mob_entry(stats, final_boss_name, boss_data)
        b_foe["ATK"] = int(b_foe["ATK"] * diff.get("dmg_mult", 1.5))
        b_foe["HP"] = int(b_foe["HP"] * diff.get("hp_mult", 1.2))
        boss_entrance(final_boss_name)
        won, _ = run_arena_style_combat(stats, b_foe)
        if won:
            victory_fanfare()
            exp_final = int(500 * diff.get("exp_mult", 1.0) * dungeon["num_floors"])
            gold_final = int(2000 * diff.get("gold_mult", 1.0) * dungeon["num_floors"])
            grant_exp(stats, exp_final)
            stats["Gold"] = stats.get("Gold", 0) + gold_final
            track_stat(stats, "bosses_defeated")
            modify_faction_standing("Iron Legion", 5, stats)
            event(f"DUNGEON COMPLETE! +{exp_final} EXP, +{gold_final} gold!", "victory")
            burst_particles(30, "bold yellow")
        else:
            event("The dungeon claims another victim...", "death")
            gold_loss = int(stats.get("Gold", 0) * 0.3)
            stats["Gold"] = max(0, stats.get("Gold", 0) - gold_loss)

def _adventure_encounter_loop(
    zone_name: str,
    pool: Dict[str, Any],
    exp_mult: float,
    gold_range: Tuple[int, int],
    drop_pool: Any,
    drop_chance: int,
    zone_key: str = "",
) -> None:
    global stats
    encounters = 0
    weather = roll_weather(zone_key) if zone_key else WEATHER_EFFECTS["clear"]
    diff = SETTINGS.get_difficulty()
    apply_time_regen(stats)
    while True:
        encounters += 1
        if encounters > 1 and zone_key:
            if random.random() < 0.35:
                describe_zone_ambient(zone_key)
                time.sleep(0.5)
            if random.random() < 0.2:
                weather = roll_weather(zone_key)
            describe_weather_now(weather)
            if random.random() < 0.15:
                zone_event = roll_zone_event(zone_key)
                if zone_event: process_zone_event(stats, zone_event)
            if encounters % 3 == 0 and random.random() < 0.4:
                enhanced_rest_at_camp(stats, 0.3)
            if random.random() < 0.1:
                extra_enc = roll_extra_encounter()
                if extra_enc: process_extra_encounter(stats, extra_enc)
            console.print()

        name = random.choice(list(pool.keys()))
        template = pool[name]
        foe = foe_from_mob_entry(stats, name, template)
        foe["ATK"] = int(foe["ATK"] * diff.get("dmg_mult", 1.0))
        foe["DEF"] = int(foe["DEF"] * diff.get("dmg_mult", 1.0))
        foe["HP"] = int(foe["HP"] * diff.get("hp_mult", 1.0))
        weather_mod = weather.get("combat_mod", {})
        foe["ATK"] = int(foe["ATK"] * weather_mod.get("atk", 1.0))
        foe["DEF"] = int(foe["DEF"] * weather_mod.get("def", 1.0))
        battle_intro(name)
        won, turns = run_arena_style_combat(stats, foe)
        if won:
            victory_fanfare()
            exp_gain = int(foe["lvl"] * 5 * exp_mult + template.get("EXP", 20) * diff.get("exp_mult", 1.0))
            grant_exp(stats, exp_gain)
            gold_gain = int(random.randint(gold_range[0], gold_range[1]) * diff.get("gold_mult", 1.0))
            stats["Gold"] = stats.get("Gold", 0) + gold_gain
            event(f"Victory! +{exp_gain} EXP, +{gold_gain} gold.", "loot")
            track_stat(stats, "adventures_done")
            track_stat(stats, "total_gold_earned", gold_gain)
            modify_faction_standing("Iron Legion", 1, stats)
            time.sleep(0.5)
            if random.random() < diff.get("loot_mult", 1.0) * 0.3:
                loot_desc = get_loot_desc("uncommon")
                console.print(f"  [dim]{loot_desc}[/dim]")
            if template.get("Drops"):
                drop = random.choice(template["Drops"])
                stats["Backpack"].append(drop)
                item_desc = get_item_description(drop.get("Name", ""))
                event(f"Loot: {drop['Name']}!", "loot")
                time.sleep(0.5)
            elif drop_pool and random.randint(1, 100) <= int(drop_chance * diff.get("loot_mult", 1.0)):
                drop = random.choice(drop_pool)
                stats["Backpack"].append(drop)
                event(f"Loot: {drop['Name']}!", "loot")
                time.sleep(0.5)
            death_desc = get_enemy_death_desc(name)
            console.print(f"  [dim]{death_desc}[/dim]")
            time.sleep(0.3)
            clear()
            cont = console.input("Continue exploring? (yes/no): ").lower().strip()
            clear()
            if cont != "yes":
                zone_header("RETURNING TO TOWN", f"Leaving the {zone_name} behind", "bright_cyan")
                type(f"You return from the {zone_name} with your spoils.", style="bold white")
                shake_screen(1, 0.2)
                time.sleep(0.8)
                clear()
                return
        else:
            flash_screen("red", 0.3)
            type(f"You were defeated in the {zone_name}!", style="bold white on red")
            time.sleep(0.5)
            gold_loss = int(stats.get("Gold", 0) * 0.1)
            stats["Gold"] = max(0, stats.get("Gold", 0) - gold_loss)
            event(f"You lost {gold_loss} gold.", "damage")
            track_stat(stats, "total_gold_spent", gold_loss)
            modify_faction_standing("Iron Legion", -1, stats)
            time.sleep(0.5)
            if random.randint(1, 100) <= 25 and stats.get("Backpack"):
                lost = random.choice(stats["Backpack"])
                stats["Backpack"].remove(lost)
                event(f"You lost {lost['Name']}!", "death")
                time.sleep(0.5)
            clear()
            return

def adventure() -> None:
    global stats
    screen_title("⚔ ADVENTURE ⚔", "Choose your destination")
    describe_time_of_day(get_time_of_day())
    dialogue("The world is vast and dangerous. Where will you go?", "narrator", 0.03)
    time.sleep(0.3)
    clear()
    while True:
        zone_header("CHOOSE YOUR PATH", "Each zone offers unique challenges and rewards", "bright_cyan")
        console.print()
        console.print("  [bold cyan]1.[/bold cyan]  [bold white]Crimson Fields[/bold white]  [dim](lvl 1-19 · Goblins & Trolls)[/dim]")
        console.print("  [bold cyan]2.[/bold cyan]  [bold white]Rotfang Depths[/bold white]  [dim](lvl 20-49 · Shamans & Elementals)[/dim]")
        console.print("  [bold cyan]3.[/bold cyan]  [bold white]Boss Arena[/bold white]  [dim](lvl 50+ · Epic Boss Fights)[/dim]")
        console.print("  [bold cyan]4.[/bold cyan]  [bold white]Dungeon Dive[/bold white]  [dim](Procedural dungeon)[/dim]")
        console.print("  [bold cyan]5.[/bold cyan]  [bold white]Return to town[/bold white]")
        console.print()
        try:
            choice = int_prompt("Where to: ")
        except ValueError:
            choice = 0
        clear()
        if choice == 5:
            dialogue("You head back to the safety of town.", "narrator")
            time.sleep(0.3)
            clear()
            return
        elif choice == 4:
            dungeon_adventure(stats)
            clear()
        elif choice == 1:
            start("Crimson Fields", "Entering", 2, 5)
            clear()
            screen_title("CRIMSON FIELDS", "An ancient battlefield stained by war")
            describe_zone_entry("crimson")
            weather = roll_weather("crimson")
            describe_weather_now(weather)
            explore_zone_dialogue("crimson")
            flash_screen("red", 0.1)
            time.sleep(0.5)
            clear()
            _adventure_encounter_loop("Crimson Fields", soldiers, 1, (50, 200), swords, 30, "crimson")
        elif choice == 2:
            if stats.get("Lvl", 1) < 20:
                type("The Rotfang Depths are too dangerous below level 20!")
                flash_screen("red", 0.1)
                time.sleep(1)
                clear()
                continue
            start("Rotfang Depths", "Descending", 2, 5)
            clear()
            screen_title("ROTFANG DEPTHS", "Dark caverns where ancient evils slumber")
            describe_zone_entry("rotfang")
            weather = roll_weather("rotfang")
            describe_weather_now(weather)
            explore_zone_dialogue("rotfang")
            flash_screen("blue", 0.15)
            burst_particles(6, "bold blue")
            time.sleep(0.5)
            clear()
            _adventure_encounter_loop("Rotfang Depths", monsters, 2, (500, 2000), None, 0, "rotfang")
        elif choice == 3:
            if stats.get("Lvl", 1) < 50:
                type("The Boss Arena is for level 50+ adventurers only!")
                flash_screen("red", 0.2)
                time.sleep(1)
                clear()
                continue
            screen_title("BOSS ARENA", "Face the mightiest foes in the realm")
            dialogue("You step into the arena as the gates slam shut behind you...", "narrator", 0.03)
            flash_screen("yellow", 0.2)
            time.sleep(0.3)
            clear()
            rotfang_depths()
        else:
            type("Invalid choice.")
            flash_screen("red", 0.05)
            time.sleep(0.5)
            clear()

def rotfang_depths() -> None:
    global stats
    type("Cold wind rises from Rotfang Depths. Bosses guarding Celestium Prisms stir below.\n")
    time.sleep(0.35)
    names = list(boss.keys())
    for i, n in enumerate(names, start=1):
        prism_ct = boss[n].get("Prisms", 1)
        type(f"{i}. {n} (~{boss[n]['EXP']} EXP · {prism_ct} prism(s))")
        time.sleep(0.05)
    pick = int_prompt("Choose a foe (number), or 0 to leave: ")
    clear()
    if pick == 0:
        type("You climb back toward town.\n")
        time.sleep(0.4)
        clear()
        return
    title = names[pick - 1]
    bdata = boss[title]
    type(f"You drop into the depths to challenge {title}!")
    time.sleep(0.85)
    clear()
    foe = foe_from_boss_entry(stats, title, bdata)
    won, turns = run_arena_style_combat(stats, foe)
    if won:
        prisms = bdata.get("Prisms", 1)
        stats["Celestium Prism"] = stats.get("Celestium Prism", 0) + prisms
        boss_exp = float(bdata.get("EXP", 400))
        grant_exp(stats, boss_exp + max(50, stats["Lvl"] * 5))
        gold_bonus = boss_exp + turns * 3
        stats["Gold"] += int(gold_bonus)
        stats["Reputation"] = stats.get("Reputation", 0) + 2
        stats["bosses_defeated"] = stats.get("bosses_defeated", 0) + 1
        modify_faction_standing("Iron Legion", 5, stats)
        death_desc = get_enemy_death_desc(title)
        console.print(f"  [dim]{death_desc}[/dim]")
        type(f"{title} falls! Celestium Prisms gained: +{prisms}. Bonus gold: +{int(gold_bonus)}.")
        time.sleep(0.9)
    else:
        stats["deaths"] = stats.get("deaths", 0) + 1
        modify_faction_standing("Shadow Guild", 2, stats)
        type("You barely escape Rotfang Depths alive...")
        time.sleep(0.9)
    clear()

