def shop():
    global stats
    rep_discount = reputation_discount(stats)
    rep_surcharge = reputation_surcharge(stats)
    if rep_discount < 1.0:
        dialogue(f"Ah, a valued customer! I'll give you a {int((1-rep_discount)*100)}% discount!", "merchant", 0.03)
    screen_title("🏪 THE EMPORIUM", "Rare goods, fair prices, no questions asked")
    dialogue(get_merchant_buy_response(), "merchant", 0.03)
    time.sleep(0.3)
    clear()
    start("Shop", "Loading", 3, 7.5)
    clear()
    gold_count = stats.get("Gold", 0)
    title = get_player_title(stats.get("Lvl", 1))
    zone_header("THE EMPORIUM", f"You have {gold_count} gold  ·  Your title: {title}", "bright_yellow")
    console.print()
    console.print("  [bold cyan]1.[/bold cyan]  [bold white]Buy Items[/bold white]  [dim](Swords · Potions · Armor)[/dim]")
    console.print("  [bold cyan]2.[/bold cyan]  [bold white]Sell Items[/bold white]  [dim](Empty your backpack)[/dim]")
