    if shop == "2" or shop == "sell":
        for index, item in enumerate(stats["Backpack"], start=1):
            console.print(f"Item {index}:")
            for key, value in item.items():
                console.print(f"   {key}: {value}")
        sell = console.input("What would you like to sell(Type 1 if you want to leave) (Capitalization counts): ")
        clear()
        if sell == "1":
            pass
        else:
            found = False
            for item in stats["Backpack"]:
                if item.get("Name") == sell:
                    found = True
                    break
            if found:
                console.print(f"🎉 {sell} found!")
                cost = 0
                for item in stats["Backpack"]:
                    if item["Name"] == sell:
                        cost = item["Cost"]
                        break
                lower = cost / 20
                upper = cost / 10
                cost_range = random.uniform(lower, upper)
                console.print(cost_range)
                time.sleep(1)
                clear()
                for item in stats["Backpack"]:
                    if item.get("Name") == sell:
                        console.print(f"📦 Stats for {sell}:")
                        time.sleep(0.1)
                        for key, value in item.items():
                            time.sleep(0.1)
                            console.print(f"   {key}: {value}")
                        break
                price = int_prompt(f"Enter the price you want to sell {sell} for: ")
                cost = 0
                for item in stats["Backpack"]:
                    if item["Name"] == sell:
                        cost = item["Cost"]
                        break
                if price > cost + cost_range:
                    console.print(f"The shopkeeper sells {sell} for {cost / 2} gold because you put a price that is higher than the range. 😭😭😭 Caught in 4K moments 👀")
                    time.sleep(2)
                    clear()
                    stats["Gold"] += cost / 2
                    stats["Backpack"] = [
                        item for item in stats["Backpack"] if item["Name"] != sell
                    ]
                else:
                    console.print(f"The shopkeeper sells {sell} for {price} gold. 🎉🎉🎉")
                    time.sleep(1)
                    clear()
                    stats["Gold"] += price
                    stats["Backpack"] = [
                        item for item in stats["Backpack"] if item["Name"] != sell
                    ]
            else:
                console.print(f"{sell} not found!")
                time.sleep(1)
                clear()
