def goldspire_market(): 
    if stats["Lvl"] <= 24:
        flash_screen("red", 0.1)
        type("The Goldspire Market is for adventurers level 25 and above!")
        time.sleep(2)
    else:
        screen_title("✨ GOLDSPIRE MARKET ✨", "Exclusive items for the realm''s elite")
        dialogue("Ah, a customer of refined taste! Welcome to the Goldspire Market!", "merchant", 0.03)
        time.sleep(0.2)
        dialogue("We deal in the finest goods — items of legend, artifacts of power!", "merchant", 0.03)
        time.sleep(0.2)
        clear()
        start("Goldspire Market", "Loading", 1, 4)
        clear()
        while True:
            zone_header("GOLDSPIRE MARKET", "Premium items · Dragonite & Diamond accepted", "bright_yellow")
            console.print()
            console.print("  [bold cyan]1.[/bold cyan]  [bold white]Exclusive Items[/bold white]  [dim](Mythic gear)[/dim]")
            console.print("  [bold cyan]2.[/bold cyan]  [bold white]World Trading[/bold white]  [dim](Trade with other players)[/dim]")
            console.print("  [bold cyan]3.[/bold cyan]  [bold white]Browse Artifacts[/bold white]  [dim](Legendary artifacts)[/dim]")
            console.print("  [bold cyan]4.[/bold cyan]  [bold white]Leave[/bold white]")
            console.print()
            choice = int_prompt("Enter your choice: ")
            clear()
            if choice == 1:
                exclusive_items = [
                    {"num": 1, "name": "Titan''s Heartplate", "type": "Chestplate", "stats": {"DEF": 10, "SP": 1.5}, "cost": {"Dragonite": 3, "Diamond": 5, "Gold": 10000000}},
                    {"num": 2, "name": "Dragonbone Bulwark", "type": "Shield", "stats": {"DEF": 8, "ATK": 5, "SP": 5}, "cost": {"Dragonite": 1, "Diamond": 3, "Gold": 50000000}},
                    {"num": 3, "name": "Crownbreaker Halberd", "type": "Weapon", "stats": {"ATK": 10, "SP": 1.5}, "cost": {"Dragonite": 5, "Diamond": 10, "Gold": 2000000}},
                    {"num": 4, "name": "Heart of the Colossus", "type": "Artifact", "stats": {"ATK": 10, "DEF": 10, "SP": 10}, "cost": {"Dragonite": 15, "Diamond": 30, "Gold": 1000000000}},
                ]
                section("EXCLUSIVE ITEMS")
                for ex in exclusive_items:
                    cost_str = ", ".join(f"{v} {k}" for k, v in ex["cost"].items())
                    stat_str = ", ".join(f"{k}: {v}" for k, v in ex["stats"].items())
                    console.print(f"  [bold cyan]{ex['num']}.[/bold cyan] [bold white]{ex['name']}[/bold white] [dim]({ex['type']})[/dim]")
                    console.print(f"       [dim]{stat_str}[/dim]")
                    console.print(f"       [bold yellow]Cost:[/bold yellow] {cost_str}")
                    console.print()
                item = int_prompt("Enter the number of the item you want to buy (0 to cancel): ")
                clear()
                if 1 <= item <= len(exclusive_items):
                    ex = exclusive_items[item - 1]
                    can_buy = True
                    for mat, amt in ex["cost"].items():
                        if stats.get(mat, 0) < amt:
                            can_buy = False
                            type(f"Not enough {mat}!", style="bold red")
                            break
                    if can_buy:
                        equip_card(ex["name"], ex["stats"])
                        buy = console.input("Do you want to buy this item (yes/no): ").lower()
                        clear()
                        if buy == "yes":
                            for mat, amt in ex["cost"].items():
                                stats[mat] -= amt
                            if ex["type"] == "Chestplate":
                                stats["Chestplate"] = {"Name": ex["name"], "MAX DUR": 100000000000, "DUR": 100000000000, **ex["stats"]}
                            elif ex["type"] == "Shield":
                                stats["Left Hand"] = {"Name": ex["name"], "MAX DUR": 100000000000, "DUR": 100000000000, "Class": "Shield", **ex["stats"]}
                            elif ex["type"] == "Weapon":
                                stats["Weapon"] = {"Name": ex["name"], "MAX DUR": 100000000000, "DUR": 100000000000, "Class": "Weapon", **ex["stats"]}
                            elif ex["type"] == "Artifact":
                                stats["Backpack"].append({"Name": ex["name"], "MAX DUR": 100000000000, "DUR": 100000000000, "Class": "Artifact", **ex["stats"]})
                            rainbow_text(f"★ PURCHASED: {ex['name']} ★")
                            burst_particles(15, "bold yellow")
                time.sleep(1)
                clear()
            elif choice == 2:
                _world_trading_inline()
            elif choice == 3:
                section("LEGENDARY ARTIFACTS")
                dialogue("These are the rarest of the rare. Handle with care!", "merchant", 0.03)
                for art in artifacts:
                    console.print(f"  [bold cyan]{art['Name']}[/bold cyan]")
                    for k, v in art.items():
                        if k != "Name":
                            console.print(f"    [dim]{k}: {v}[/dim]")
                    console.print()
                console.input("[dim]Press Enter to continue...[/dim]")
                clear()
            elif choice == 4:
                dialogue("Come back anytime, wealthy adventurer!", "merchant")
                break
            else:
                type("Invalid choice.")
                time.sleep(0.5)
                clear()

