def obsidian_anvil():
    type("Welcome to the Obsidian Anvil!")
    time.sleep(0.7)
    clear()
    level = 0
    if stats["Diamond"] == 0:
        type("You don't have diamonds! Obtain Diamonds by mining in Crimson Depths!")
        time.sleep(2)
        clear()
    else:
        for item in stats["Backpack"]:
            console.print("Item details:")
            for key, value in item.items():
                console.print(f"  {key}: {value}")
            console.print()
        item = console.input("Enter the name of the item you want to repair(Capitalization counts!): ")
        clear()
        found = False
        for i in stats["Backpack"]:
            if i.get("Name") == item:
                found = True
                break
        if found:
            if stats["Diamond"] == 1:
                console.print("You can only do a level 1 repair! Cost: 1 Diamond | (20% repair)")
                time.sleep(0.2)
                hi = console.input("Type yes or no: ")
                if hi == "yes":
                    level = 1
                    stats["Diamond"] -= 1
                elif hi == "no":
                    pass
            elif stats["Diamond"] == 2:
                console.print("-------------------------")
                time.sleep(0.2)
                console.print("Level 1 Repair (20% repair)| Cost: 1 Diamond")
                time.sleep(0.2)
                console.print("-------------------------")
                time.sleep(0.2)
                console.print("Level 2 Repair (50% repair)| Cost: 2 Diamonds")
                time.sleep(0.2)
                console.print("-------------------------")
                time.sleep(0.2)
                hi = int_prompt("Enter the level of the repair you want to do | Type 0 to leave: ")
                if hi == 0:
                    pass
                else:
                    level = hi
                    stats["Diamond"] -= level
            else:
                console.print("-------------------------")
                time.sleep(0.2)
                console.print("Level 1 Repair (20% repair)| Cost: 1 Diamond")
                time.sleep(0.2)
                console.print("-------------------------")
                time.sleep(0.2)
                console.print("Level 2 Repair (50% repair)| Cost: 2 Diamonds")
                time.sleep(0.2)
                console.print("-------------------------")
                time.sleep(0.2)
                console.print("Level 3 Repair (100% repair)| Cost: 3 Diamonds")
                time.sleep(0.2)
                console.print("------------------------")
                time.sleep(0.2)
                hi = int_prompt("Enter the level of the repair you want to do | Type 0 to leave: ")
                if hi == 0:
                    pass
                else:
                    level = hi
                    stats["Diamond"] -= level
            clear()
            times = 15
            times1 = 25
            start("Repairing", "", times + (level * 5), times1 + (level * 5))
            for i in stats["Backpack"]:
                if i.get("Name") == item:
                    if level == 3:
                        i["DUR"] = i["MAX DUR"]
                    elif level == 2:
                        if i["DUR"] + (i["MAX DUR"] * 0.5) > i["MAX DUR"]:
                            i["DUR"] = i["MAX DUR"]
                        else:
                            i["DUR"] += i["MAX DUR"] * 0.5
                    elif level == 1:
                        if i["DUR"] + (i["MAX DUR"] * 0.2) > i["MAX DUR"]:
                            i["DUR"] = i["MAX DUR"]
                        else:
                            i["DUR"] += i["MAX DUR"] * 0.2
                    break
        else:
            type("Item not found!!")
            time.sleep(1)
            clear()

def tavern():
    screen_title("🍺 THE DRAGON'S BREATH TAVERN")
    dialogue("Welcome, traveler! Name your blade or try your luck!", "merchant", 0.03)
    time.sleep(0.5)
    clear()
    while True:
        zone_header("TAVERN", "Name swords, gamble, or drink your sorrows away", "bright_yellow")
        console.print()
        console.print("  [bold cyan]1.[/bold cyan]  Name a Sword")
        console.print("  [bold cyan]2.[/bold cyan]  🎲 Play Dice (2x payout)")
        console.print("  [bold cyan]3.[/bold cyan]  🎰 Slot Machine (up to 200x)")
        console.print("  [bold cyan]4.[/bold cyan]  🃏 Blackjack (double down)")
        console.print("  [bold cyan]5.[/bold cyan]  Leave the tavern")
        console.print()
        choice = int_prompt("What's your pleasure? ")
        clear()
        if choice == 1:
            for index, item in enumerate(stats["Backpack"], start=1):
                console.print(f"Item {index}:")
                for key, value in item.items():
                    console.print(f"   {key}: {value}")
            sword = console.input("Which sword would you like to name(Type 1 to leave | Capitalization counts): ")
            found = False
            for item in stats["Backpack"]:
                if item.get("Name") == sword:
                    found = True
                    break
            if not found:
                type("Sword not found!")
                time.sleep(1)
                clear()
            else:
                name = console.input("What would you like to name your sword: ")
                for item in stats["Backpack"]:
                    if item.get("Name") == sword:
                        item["Name"] = name
                        break
                rainbow_text(f"Your sword is now named {name}!")
                burst_particles(8, "bold cyan")
                time.sleep(1)
                clear()
        elif choice == 2:
            dialogue("Feeling lucky? Let's roll some dice!", "merchant")
            dice_game(stats)
            time.sleep(1)
            clear()
        elif choice == 3:
            dialogue("The slots are feeling hot today!", "drunk")
            slot_machine(stats)
            time.sleep(1)
            clear()
        elif choice == 4:
            dialogue("Careful not to bust!", "rogue")
            blackjack(stats)
            time.sleep(1)
            clear()
        elif choice == 5:
            dialogue("Come back anytime, adventurer!", "merchant")
            break
        else:
            type("The bartender gives you a confused look.")
            time.sleep(1)
            clear()

def view_stats():
    section("PLAYER STATS")
    stats_table(stats)
    if stats.get("Weapon"):
        equip_card("Weapon", stats["Weapon"])
    if stats.get("Left Hand") and stats["Left Hand"]:
        equip_card("Left Hand", stats["Left Hand"])
    for slot in ["Helmet", "Chestplate", "Leggings", "Boots"]:
        if stats.get(slot) and stats[slot]:
            equip_card(slot, stats[slot])
    if stats.get("Backpack"):
        section("BACKPACK")
        inventory_table(stats["Backpack"])
    console.print()
    stat_opt = int_prompt("[1] Continue  [2] Inventory Manager  [3] Ultimate Stats: ", default=1)
    clear()
    if stat_opt == 2:
        inventory_manager(stats)
    elif stat_opt == 3:
        ultimate_stat_display(stats)
    clear()

def change_loadout():
    console.print("------------------------")
    time.sleep(0.3)
    console.print("Weapon: ", stats["Weapon"])
    time.sleep(0.3)
    console.print("Left Hand: ", stats["Left Hand"])
    time.sleep(0.3)
    console.print("------------------------\n")
    time.sleep(0.3)
    console.print("Backpack:")
    time.sleep(0.3)
    console.print(*stats["Backpack"], sep = "\n")
    time.sleep(0.3)
    choice = console.input("\nEnter what you want to change(Weapon/Left Hand): ").lower()
    clear()
    if choice == "weapon":
        var = 0
        var1 = 0
        while var == 0:
            sword = console.input("What weapon would you like to equip(Type 1 if you want to leave): ")
            if sword == "1":
                var1 = 1
                break
            found = False
            for item in stats["Backpack"]:
                if "Name" in item and "Class" in item:
                    if item["Name"] == sword and item["Class"] == "Weapon":
                        found = True
                        break
            console.print(f"Searching for {sword}...")
            time.sleep(random.uniform(0, 4))
            if found:
                console.print("🎯 Weapon found!")
            else:
                console.print("No such weapon in the backpack!")
                time.sleep(1)
                break
            time.sleep(0.5)
            console.print(f"Equiping {sword}...")
            time.sleep(random.uniform(0, 3))
            for i in range(len(stats["Backpack"])):
                item = stats["Backpack"][i]
                if item["Name"] == sword and item["Class"] == "Weapon":
                    stats["Backpack"][i], stats["Weapon"] = stats["Weapon"], stats["Backpack"][i]
                    console.print(f"You equipped {sword}!")
                    break
            time.sleep(2)
            break
        if var1 == 1:
            pass
    else:
        var = 0
        var1 = 0
        while var == 0:
            shield = console.input("What item would you like to equip(Type 1 if you want to leave): ")
            if shield == "1":
                var1 = 1
                break
            found = False
            for item in stats["Backpack"]:
                if "Name" in item and "Class" in item:
                    if item["Name"] == shield:
                        found = True
                        break
            console.print(f"Searching for {shield}...")
            time.sleep(random.uniform(0, 4))
            if found:
                console.print("🎯 Item found!")
            else:
                console.print("No such item in the backpack!")
                time.sleep(1)
                break
            time.sleep(0.5)
            console.print(f"Equiping {shield}...")
            time.sleep(random.uniform(0, 3))
            for i in range(len(stats["Backpack"])):
                item = stats["Backpack"][i]
                if item["Name"] == shield:
                    stats["Backpack"][i], stats["Left Hand"] = stats["Left Hand"], stats["Backpack"][i]
                    console.print(f"You equipped {shield}!")
                    break
            time.sleep(2)
            break
        if var1 == 1:
            pass          

