def settings_menu():
    global stats
    while True:
        screen_title("⚙ GAME SETTINGS", "Customize your adventure")
        console.print("  [bold cyan]1.[/bold cyan]  🎨 Theme Selection")
        console.print("  [bold cyan]2.[/bold cyan]  ✨ Animation Level")
        console.print("  [bold cyan]3.[/bold cyan]  ⌨ Typing Speed")
        console.print("  [bold cyan]4.[/bold cyan]  📦 Panel Border Style")
        console.print("  [bold cyan]5.[/bold cyan]  ⚔ Difficulty Level")
        console.print("  [bold cyan]6.[/bold cyan]  🔧 Toggle Options")
        console.print("  [bold cyan]7.[/bold cyan]  💾 Save Settings")
        console.print("  [bold cyan]8.[/bold cyan]  ↩ Back to Game")
        console.print()
        choice = int_prompt("Choose: ")
        clear()
        if choice == 1:
            _settings_theme_selector()
        elif choice == 2:
            _settings_animation_selector()
        elif choice == 3:
            _settings_text_speed_selector()
        elif choice == 4:
            _settings_panel_selector()
        elif choice == 5:
            _settings_difficulty_selector()
        elif choice == 6:
            _settings_toggle_options()
        elif choice == 7:
            SETTINGS.save()
            event("Settings saved!", "success")
            time.sleep(0.5)
            clear()
        elif choice == 8:
            break
        else:
            type("Invalid choice.")
            time.sleep(0.5)
            clear()

def _settings_theme_selector():
    themes = SETTINGS.get_theme_list()
    while True:
        screen_title("🎨 THEME SELECTION", "Pick a look that suits your style")
        for i, (key, name) in enumerate(themes, 1):
            indicator = " ►" if SETTINGS.get_theme_name() == key else ""
            console.print(f"  [bold cyan]{i}.[/bold cyan] [bold white]{name}[/bold white]{indicator}")
        console.print(f"  [bold cyan]{len(themes) + 1}.[/bold cyan] [bold white]Back[/bold white]")
        console.print()
        choice = int_prompt("Choose a theme: ")
        clear()
        if 1 <= choice <= len(themes):
            key, name = themes[choice - 1]
            SETTINGS.set_theme(key)
            event(f"Theme changed to: {name}", "info")
            flash_screen(SETTINGS.color("primary"), 0.2)
            time.sleep(0.5)
            clear()
        elif choice == len(themes) + 1:
            break
        else:
            type("Invalid choice.")
            time.sleep(0.5)
            clear()

def _settings_animation_selector():
    levels = SETTINGS.get_anim_levels()
    while True:
        screen_title("✨ ANIMATION LEVEL", "Control visual effects intensity")
        console.print(f"  [dim]Current: {SETTINGS.get_anim_level().upper()}[/dim]")
        console.print()
        for i, level in enumerate(levels, 1):
            desc = {
                "off": "No animations or effects",
                "minimal": "Particles only, no shaking",
                "normal": "Standard effects and shaking",
                "max": "Full effects with cinematics",
                "insane": "Maximum chaos - EVERYTHING enabled",
            }.get(level, "")
            indicator = " ►" if SETTINGS.get_anim_level() == level else ""
            console.print(f"  [bold cyan]{i}.[/bold cyan] [bold white]{level.title()}[/bold white]{indicator}")
            console.print(f"       [dim]{desc}[/dim]")
        console.print(f"  [bold cyan]{len(levels) + 1}.[/bold cyan] [bold white]Back[/bold white]")
        console.print()
        choice = int_prompt("Choose: ")
        clear()
        if 1 <= choice <= len(levels):
            level = levels[choice - 1]
            SETTINGS.set("animation_level", level)
            event(f"Animation level: {level.title()}", "info")
            if level == "insane":
                flash_screen("yellow", 0.3)
                burst_particles(20, "bold yellow")
            time.sleep(0.5)
            clear()
        elif choice == len(levels) + 1:
            break
        else:
            type("Invalid choice.")
            time.sleep(0.5)
            clear()

