def _settings_difficulty_selector():
    diffs = SETTINGS.get_difficulty_list()
    while True:
        screen_title("⚔ DIFFICULTY", "Adjust challenge level")
        current = SETTINGS.get("difficulty", "normal")
        for i, (key, label, desc) in enumerate(diffs, 1):
            indicator = " ►" if current == key else ""
            console.print(f"  [bold cyan]{i}.[/bold cyan] [bold white]{label}[/bold white]{indicator}")
            console.print(f"       [dim]{desc}[/dim]")
        console.print(f"  [bold cyan]{len(diffs) + 1}.[/bold cyan] [bold white]Back[/bold white]")
        console.print()
        choice = int_prompt("Choose: ")
        clear()
        if 1 <= choice <= len(diffs):
            key, label, desc = diffs[choice - 1]
            SETTINGS.set("difficulty", key)
            if stats is not None:
                stats["difficulty"] = key
            event(f"Difficulty: {label}", "warning")
            time.sleep(0.3)
            clear()
        elif choice == len(diffs) + 1:
            break
        else:
            type("Invalid choice.")
            time.sleep(0.5)
            clear()

