# ============================================================
#  NEW UI ANIMATION HELPERS
# ============================================================
def animated_transition(text: str, color: str = None, frames: int = 8):
    if color is None:
        color = SETTINGS.color("primary", "bright_blue")
    if not SETTINGS.get("menu_animation", True):
        console.print(f"[bold {color}]{text}[/bold {color}]")
        return
    for i in range(frames, 0, -1):
        prefix = " " * (frames - i)
        arrow = ">" * i
        console.print(f"[bold {color}]{prefix}{arrow} {text} {arrow}[/bold {color}]", end="\r")
        time.sleep(0.03)
    console.print()

def animated_bracket(text: str, color: str = None):
    if color is None:
        color = SETTINGS.color("accent", "yellow")
    if not SETTINGS.get("menu_animation", True):
        console.print(f"[bold {color}]{text}[/bold {color}]")
        return
    brackets = ["[ ", "[-", "[=", "[= ", "[== ", "[=== ", "[==== ", "[===== "]
    for b in brackets:
        console.print(f"  [bold {color}]{b}[/bold {color}]{text}[bold {color}] =====][/bold {color}]", end="\r")
        time.sleep(0.04)
    console.print(f"  [bold {color}][=====[/bold {color}] {text} [bold {color}]=====][/bold {color}]")

def animated_progress_bar(current: int, maximum: int, width: int = 20, color: str = None):
    if color is None:
        color = SETTINGS.color("success", "green")
    ratio = current / maximum if maximum > 0 else 0
    filled = int(ratio * width)
    bar = f"[{color}]{'█' * filled}[/{color}][dim]{'░' * (width - filled)}[/dim]"
    if not SETTINGS.get("menu_animation", True):
        console.print(f"{bar} {current}/{maximum}")
        return
    for i in range(filled + 1):
        temp_bar = f"[{color}]{'█' * i}[/{color}][dim]{'░' * (width - i)}[/dim]"
        console.print(f"{temp_bar} {int(i / width * maximum)}/{maximum}", end="\r")
        time.sleep(0.01)
    console.print()

def scroll_title(text: str, color: str = None):
    if color is None:
        color = SETTINGS.color("primary", "bright_blue")
    if not SETTINGS.get("menu_animation", True):
        section(text)
        return
    chars = list(str(text))
    for i in range(len(chars) + 1):
        line = "".join(chars[:i])
        console.print(f"[bold {color}]{line}[/bold {color}]", end="\r")
        time.sleep(0.02)
    console.print()

def flash_border(console_obj, color: str = None, times: int = 3):
    if color is None:
        color = SETTINGS.color("border", "bright_blue")
    if not SETTINGS.get("border_animation", False):
        return
    original_color = console_obj.style
    for _ in range(times):
        console_obj.style = color
        time.sleep(0.05)
        console_obj.style = original_color if original_color else ""
        time.sleep(0.05)



# ============================================================
#  WEATHER GENERATION
# ============================================================
def roll_weather(zone_key: str = "crimson") -> Dict[str, Any]:
    zone = ZONE_THEMES.get(zone_key, ZONE_THEMES["crimson"])
    weights = zone.get("weather_weights", {"clear": 50, "rain": 20, "fog": 15, "windy": 10, "heatwave": 5})
    pool = []
    for weather, weight in weights.items():
        pool.extend([weather] * weight)
    choice = random.choice(pool) if pool else "clear"
    return WEATHER_EFFECTS.get(choice, WEATHER_EFFECTS["clear"])

def apply_weather_mods(stats: Dict[str, Any], weather: Dict[str, Any]) -> Dict[str, float]:
    mods = weather.get("combat_mod", {})
    result = {
        "atk": stats.get("STR", 100) * mods.get("atk", 1.0),
        "def": stats.get("DEF", 50) * mods.get("def", 1.0),
        "sp": stats.get("SP", 20) * mods.get("sp", 1.0),
        "crit": stats.get("Crit", 5) * mods.get("crit", 1.0),
    }
    return result

def describe_weather_now(weather: Dict[str, Any]) -> None:
    icon = weather.get("icon", "☀")
    name = weather.get("name", "Clear")
    desc = weather.get("desc", "")
    console.print(f"  {icon} [bold]{name}[/bold] — [dim]{desc}[/dim]")
    time.sleep(0.3)

