def roll_zone_event(zone_key: str) -> Dict[str, Any]:
    events = ZONE_EVENTS.get(zone_key, [])
    if not events:
        return None
    pool = []
    for event in events:
        pool.extend([event] * event.get("weight", 10))
    return random.choice(pool) if pool else None

def process_zone_event(stats: Dict[str, Any], event: Dict[str, Any]) -> None:
    if event is None:
        return
    event_name = event.get("name", "Unknown Event")
    event_desc = event.get("desc", "")
    effect = event.get("effect", "")
    screen_title(f"📍 {event_name}")
    dialogue(event_desc, "narrator", 0.03)
    time.sleep(0.3)
    if effect == "loot":
        loot_items = event.get("loot", [])
        for li in loot_items:
            name = li.get("Name", "Item")
            qty = li.get("Qty", (1, 1))
            count = random.randint(qty[0], qty[1]) if isinstance(qty, (list, tuple)) else 1
            item = dict(li)
            item.pop("Qty", None)
            item["Class"] = item.get("Class", "Material")
            stats["Backpack"].append(item)
            for _ in range(count - 1):
                stats["Backpack"].append(dict(item))
            event(f"Found: {name} x{count}", "loot")
    elif effect == "gold":
        gold_range = event.get("gold", (0, 0))
        gold = random.randint(gold_range[0], gold_range[1])
        stats["Gold"] = stats.get("Gold", 0) + gold
        event(f"Gained {gold} gold!", "gold")
    elif effect == "buff":
        buff_name = event.get("buff", "")
        if buff_name == "temporary_defense":
            stats["_temp_def_buff"] = stats.get("_temp_def_buff", 0) + 5
            event("+5 temporary defense gained!", "shield")
        elif buff_name == "crafting_boost":
            stats["_crafting_boost"] = stats.get("_crafting_boost", 0) + 1
            event("Crafting skill temporarily boosted!", "enchant")
    elif effect == "choice":
        options = event.get("options", ["Yes", "No"])
        console.print()
        for i, opt in enumerate(options, 1):
            console.print(f"  [bold cyan]{i}.[/bold cyan] {opt}")
        choice = int_prompt("What do you do? ")
        if choice == 1:
            event("You act decisively!", "info")
        elif choice == 2:
            event("You take the cautious approach.", "info")
        else:
            event("You find a creative solution.", "magic")
    elif effect == "combat":
        event("Prepare for battle!", "danger")
    elif effect == "chase":
        gold_range = event.get("gold", (0, 0))
        gold = random.randint(gold_range[0], gold_range[1])
        event(f"You chase down the goblin and recover {gold} gold!", "loot")
        stats["Gold"] = stats.get("Gold", 0) + gold
    time.sleep(0.5)
    clear()

