def roll_random_loot_from_table(zone_key: str, rarity: str = "common") -> Dict[str, Any]:
    table = LOOT_TABLES.get(zone_key, LOOT_TABLES["crimson"])
    items = table.get(rarity, [])
    if not items:
        return None
    return random.choice(items)

def roll_expanded_loot(stats: Dict[str, Any], zone_key: str) -> List[Dict[str, Any]]:
    rewards = []
    roll = random.randint(1, 100)
    if roll <= 50:
        loot = roll_random_loot_from_table(zone_key, "common")
        if loot:
            rewards.append(loot)
    elif roll <= 80:
        loot = roll_random_loot_from_table(zone_key, "uncommon")
        if loot:
            rewards.append(loot)
    elif roll <= 95:
        loot = roll_random_loot_from_table(zone_key, "rare")
        if loot:
            rewards.append(loot)
    else:
        rewards.append({"Name": "Diamond", "Class": "Material"})
        rewards.append({"Name": "Magic Essence", "Class": "Material"})
    return rewards

