def enhanced_rest_at_camp(stats: Dict[str, Any], heal_percent: float = 0.5) -> None:
    flavor = random.choice(CAMP_FLAVOR)
    console.print(f"[dim italic]{flavor}[/dim italic]")
    time.sleep(0.3)
    event_data = roll_camp_event()
    name = event_data.get("name", "Quiet Night")
    desc = event_data.get("desc", "")
    heal_bonus = event_data.get("heal_bonus", 0)
    exp_bonus = event_data.get("exp_bonus", 0)
    loot = event_data.get("loot", None)
    if SETTINGS.get("show_tips", True):
        console.print(f"  [bold {SETTINGS.color('accent')}]{name}[/bold {SETTINGS.color('accent')}]")
        console.print(f"  [dim]{desc}[/dim]")
        time.sleep(0.3)
    total_heal_pct = heal_percent + heal_bonus
    heal = int(stats.get("Max HP", stats.get("HP", 1000)) * max(0.1, total_heal_pct))
    stats["HP"] = min(stats.get("Max HP", stats["HP"]), stats.get("HP", 0) + heal)
    event(f"Rested. +{heal} HP ({stats['HP']}/{stats.get('Max HP', stats['HP'])}).", "heal")
    if exp_bonus > 0:
        grant_exp(stats, exp_bonus)
        event(f"Gained {exp_bonus} bonus EXP!", "levelup")
    if loot:
        for li in loot:
            name = li.get("Name", "Item")
            qty = li.get("Qty", (1, 1))
            count = random.randint(qty[0], qty[1]) if isinstance(qty, (list, tuple)) else 1
            if name == "Gold":
                stats["Gold"] = stats.get("Gold", 0) + count
                event(f"Found {count} gold!", "gold")
            else:
                item = dict(li)
                item.pop("Qty", None)
                item["Class"] = item.get("Class", "Material")
                for _ in range(count):
                    stats["Backpack"].append(dict(item))
                event(f"Found: {name} x{count}", "loot")
    time.sleep(0.3)

