def expanded_random_quality():
    roll = random.randint(1, 100)
    if roll <= 25: return "cracked"
    if roll <= 45: return "worn"
    if roll <= 60: return "standard"
    if roll <= 72: return "polished"
    if roll <= 80: return "superior"
    if roll <= 86: return "masterwork"
    if roll <= 90: return "legendary"
    if roll <= 93: return "ancient"
    if roll <= 95: return "eldritch"
    if roll <= 96: return "primordial"
    if roll <= 97: return "aetherial"
    if roll <= 98: return "mythic"
    if roll <= 99: return "blessed"
    return "corrupted"

