def apply_status_effect(target: Dict[str, Any], effect_key: str, duration: int = None) -> bool:
    effect = STATUS_EFFECTS.get(effect_key)
    if not effect:
        return False
    if "status_effects" not in target:
        target["status_effects"] = {}
    if duration is None:
        duration = effect.get("duration", 3)
    target["status_effects"][effect_key] = duration
    name = effect.get("name", effect_key)
    event(f"Afflicted with: {name}!", effect.get("color", "red"))
    return True

def tick_status_effects(target: Dict[str, Any]) -> List[str]:
    messages = []
    effects = target.get("status_effects", {})
    expired = []
    for effect_key, duration in effects.items():
        effect = STATUS_EFFECTS.get(effect_key)
        if not effect:
            expired.append(effect_key)
            continue
        dmg = effect.get("damage_per_turn", 0)
        if dmg > 0:
            dmg_amount = int(target.get("HP", 0) * dmg)
            target["HP"] = max(0, target.get("HP", 0) - dmg_amount)
            name = effect.get("name", effect_key)
            icon = effect.get("icon", "")
            messages.append(f"{icon} {name}: -{dmg_amount} HP")
        elif dmg < 0:
            heal_amount = int(target.get("Max HP", 1000) * abs(dmg))
            target["HP"] = min(target.get("Max HP", 1000), target.get("HP", 0) + heal_amount)
            name = effect.get("name", effect_key)
            icon = effect.get("icon", "")
            messages.append(f"{icon} {name}: +{heal_amount} HP")
        new_duration = duration - 1
        if new_duration <= 0:
            expired.append(effect_key)
        else:
            target["status_effects"][effect_key] = new_duration
    for key in expired:
        del target["status_effects"][key]
        eff = STATUS_EFFECTS.get(key, {})
        name = eff.get("name", key)
        messages.append(f"{name} has worn off.")
    return messages

