def level_up_choice_menu(stats: Dict[str, Any]) -> None:
    screen_title("⬆ LEVEL UP!", "Choose your reward")
    for i, choice in enumerate(LEVEL_UP_CHOICES, 1):
        console.print(f"  [bold cyan]{i}.[/bold cyan] [bold white]{choice['desc']}[/bold white]")
    console.print()
    pick = int_prompt("Choose your reward: ")
    clear()
    if 1 <= pick <= len(LEVEL_UP_CHOICES):
        ch = LEVEL_UP_CHOICES[pick - 1]
        key = ch["key"]
        amount = ch["amount"]
        if key == "HP":
            stats["Max HP"] = stats.get("Max HP", 1000) + amount
            stats["HP"] = stats.get("HP", 0) + amount
        elif key == "Gold":
            stats["Gold"] = stats.get("Gold", 0) + amount
        else:
            stats[key] = stats.get(key, 0) + amount
        event(f"{ch['name']} increased by {amount}!", "levelup")
        burst_particles(10, "bold yellow")
        time.sleep(0.5)
    else:
        event("No reward chosen.", "info")

