def use_item(stats: Dict[str, Any], item_name: str) -> bool:
    backpack = stats.get("Backpack", [])
    for i, item in enumerate(backpack):
        if item.get("Name") == item_name:
            cls = item.get("Class", "")
            if "Potion of Healing" in cls or "Elixir of Life" in cls:
                heal = item.get("Effect", 500)
                stats["HP"] = min(stats.get("Max HP", stats["HP"]), stats.get("HP", 0) + heal)
                flv = get_potion_use_desc("healing")
                console.print(f"  [dim]{flv}[/dim]")
                event(f"Used {item_name}. Healed {heal} HP!", "heal")
                backpack.pop(i)
                return True
            elif "Elixir" in cls:
                heal = item.get("Effect", 5000)
                stats["HP"] = min(stats.get("Max HP", stats["HP"]), stats.get("HP", 0) + heal)
                flv = get_potion_use_desc("healing")
                console.print(f"  [dim]{flv}[/dim]")
                event(f"Used {item_name}. Healed {heal} HP!", "heal")
                backpack.pop(i)
                return True
            elif "Potion of Strength" in cls:
                boost = item.get("Effect", 2)
                stats["_str_boost"] = stats.get("_str_boost", 0) + boost
                stats["STR"] = stats.get("STR", 0) + boost
                flv = get_potion_use_desc("strength")
                console.print(f"  [dim]{flv}[/dim]")
                event(f"Used {item_name}. +{boost} STR!", "buff")
                backpack.pop(i)
                return True
            elif "Potion of Defense" in cls:
                boost = item.get("Effect", 2)
                stats["_def_boost"] = stats.get("_def_boost", 0) + boost
                stats["DEF"] = stats.get("DEF", 0) + boost
                flv = get_potion_use_desc("defense")
                console.print(f"  [dim]{flv}[/dim]")
                event(f"Used {item_name}. +{boost} DEF!", "buff")
                backpack.pop(i)
                return True
            elif "Potion of Speed" in cls:
                boost = item.get("Effect", 5)
                stats["_sp_boost"] = stats.get("_sp_boost", 0) + boost
                stats["SP"] = stats.get("SP", 0) + boost
                flv = get_potion_use_desc("speed")
                console.print(f"  [dim]{flv}[/dim]")
                event(f"Used {item_name}. +{boost} SPD!", "buff")
                backpack.pop(i)
                return True
            elif "Potion of Crit" in cls:
                boost = item.get("Effect", 5)
                stats["_crit_boost"] = stats.get("_crit_boost", 0) + boost
                stats["Crit"] = stats.get("Crit", 0) + boost
                flv = get_potion_use_desc("crit")
                console.print(f"  [dim]{flv}[/dim]")
                event(f"Used {item_name}. +{boost} CRIT!", "buff")
                backpack.pop(i)
                return True
            else:
                event(f"Cannot use {item_name} here.", "warning")
                return False
    event(f"Item not found: {item_name}", "warning")
    return False

