def generate_enemy_variant(base_monster: Dict[str, Any]) -> Tuple[str, Dict[str, Any]]:
    trait = random.choice(ENEMY_TRAITS)
    name = trait["name"]
    variant = dict(base_monster)
    variant["ATK"] = int(variant.get("ATK", 100) * trait.get("atk_mod", 1.0))
    variant["DEF"] = int(variant.get("DEF", 50) * trait.get("def_mod", 1.0))
    variant["SP"] = int(variant.get("SP", 20) * trait.get("sp_mod", 1.0))
    variant["EXP"] = int(variant.get("EXP", 20) * trait.get("exp_mod", 1.0))
    return f"{name} {base_monster.get('name', 'Monster')}", variant

# ============================================================
#  CURRENCY CONVERSION
# ============================================================
CURRENCY_RATES = {
    "Gold": 1,
    "Diamond": 10000,
    "Dragonite": 100000,
    "Celestium Prism": 1000000,
}

def convert_currency(from_curr: str, to_curr: str, amount: int, stats: Dict[str, Any]) -> bool:
    if from_curr not in CURRENCY_RATES or to_curr not in CURRENCY_RATES:
        event("Invalid currency type.", "warning")
        return False
    from_rate = CURRENCY_RATES[from_curr]
    to_rate = CURRENCY_RATES[to_curr]
    gold_value = amount * from_rate
    if stats.get(from_curr, 0) < amount:
        event(f"Not enough {from_curr}!", "warning")
        return False
    converted_amount = int(gold_value / to_rate)
    stats[from_curr] = stats.get(from_curr, 0) - amount
    stats[to_curr] = stats.get(to_curr, 0) + converted_amount
    event(f"Converted {amount} {from_curr} to {converted_amount} {to_curr}!", "gold")
    return True

