def describe_difficulty(diff_key: str) -> str:
    diff = DIFFICULTY_EXPANDED.get(diff_key, DIFFICULTY["normal"])
    label = diff.get("label", "Normal")
    desc = diff.get("desc", "")
    dmg = diff.get("dmg_mult", 1.0)
    gold = diff.get("gold_mult", 1.0)
    exp = diff.get("exp_mult", 1.0)
    loot = diff.get("loot_mult", 1.0)
    hp = diff.get("hp_mult", 1.0)
    return (
        f"[bold]{label}[/bold] - {desc}\n"
        f"  Damage: x{dmg} | Gold: x{gold} | EXP: x{exp}\n"
        f"  Loot: x{loot} | Enemy HP: x{hp}"
    )

