#  RANDOM WEAPON GENERATOR
# ============================================================
def generate_random_weapon(level: int) -> Dict[str, Any]:
    atk_base = 1.5 + (level * 0.1)
    sp_base = 0.8 + (level * 0.02)
    crit_base = 0.5 + (level * 0.03)
    dur_base = 50 + (level * 5)
    cost_base = 500 + (level * 200)
    prefix = random.choice(WEAPON_PREFIXES_EXTRA)
    suffix = random.choice(WEAPON_SUFFIXES_EXTRA)
    name = f"{prefix} Blade {suffix}"
    variance = random.uniform(0.8, 1.2)
    return {
        "Name": name,
        "ATK": round(atk_base * variance, 1),
        "SP": round(sp_base * variance, 1),
        "Crit": round(crit_base * variance, 1),
        "MAX DUR": int(dur_base),
        "DUR": int(dur_base),
        "Class": "Weapon",
        "Cost": int(cost_base),
    }

# ============================================================
#  RANDOM ARMOR GENERATOR
# ============================================================
def generate_random_armor(level: int, slot: str) -> Dict[str, Any]:
    def_base = 1.0 + (level * 0.08)
    sp_base = 0.8 + (level * 0.015)
    dur_base = 100 + (level * 10)
    cost_base = 300 + (level * 150)
    slot_names = {
        "Helmet": ["Guardian Crown", "Warrior Helm", "Ancient Crown", "Soul Veil"],
        "Chestplate": ["Battle Plate", "Guardian Armor", "Dragon Mail", "Phoenix Vest"],
        "Leggings": ["War Greaves", "Knight Legs", "Scale Trousers", "Guardian Legs"],
        "Boots": ["Battle Boots", "Knight Sabatons", "Swift Treads", "Guardian Boots"],
    }
    names = slot_names.get(slot, ["Random Armor"])
    name = random.choice(names)
    quality = random_quality()
    variance = random.uniform(0.85, 1.15)
    item = {
        "Name": name,
        "DEF": round(def_base * variance, 1),
        "SP": round(sp_base * variance, 1),
        "MAX DUR": int(dur_base),
        "DUR": int(dur_base),
        "Class": slot,
        "Cost": int(cost_base),
    }
    return apply_quality(item, quality)

