def get_faction_title(faction: str, standing: int) -> str:
    titles = FACTION_TITLES.get(faction, [])
    title = "Unknown"
    for threshold, t in titles:
        if standing >= threshold:
            title = t
    return title

def modify_faction_standing(faction: str, amount: int, stats: Dict[str, Any]) -> None:
    if "factions" not in stats:
        stats["factions"] = {}
    if faction not in stats["factions"]:
        stats["factions"][faction] = 0
    stats["factions"][faction] += amount
    title = get_faction_title(faction, stats["factions"][faction])
    direction = "increased" if amount > 0 else "decreased"
    event(f"{faction} standing {direction} by {abs(amount)}! Current: {title}", "info")

