def generate_merchant_inventory(player_level: int) -> Dict[str, List[Dict[str, Any]]]:
    inventory = {}
    for shop_type, shop_data in SHOP_INVENTORIES.items():
        items = []
        for item in shop_data["items"]:
            if item.get("Cost", 0) <= player_level * 2000:
                items.append(item)
        if not items:
            items = shop_data["items"][:2]
        if len(items) > 5:
            items = random.sample(items, min(5, len(items)))
        inventory[shop_type] = items
    return inventory

