def roll_special_event(player_level: int) -> Dict[str, Any]:
    eligible = [e for e in SPECIAL_EVENTS if e["level_min"] <= player_level]
    if not eligible:
        return None
    pool = []
    for event in eligible:
        pool.extend([event] * event["weight"])
    return random.choice(pool) if pool else None

def describe_special_event(event: Dict[str, Any]) -> None:
    if event is None:
        return
    name = event.get("name", "Event")
    desc = event.get("desc", "")
    effect = event.get("effect", "")
    screen_title(f"🌟 {name}")
    dialogue(desc, "narrator", 0.03)
    time.sleep(0.3)
    if effect == "loot":
        loot = event.get("loot", [])
        for li in loot:
            qty = li.get("Qty", (1, 1))
            count = random.randint(qty[0], qty[1])
            event(f"Found {li.get('Name', 'Item')} x{count}!", "loot")
        burst_particles(15, "bold yellow")
    elif effect == "celebration":
        event("The festivities lift your spirits!", "info")
        event("+100 EXP for participating!", "levelup")
        grant_exp(None, 100) if False else None
    elif effect == "tournament":
        event("The tournament is announced! Come test your mettle!", "boss")
    time.sleep(0.5)
    clear()

# ============================================================
#  EXPANDED MENU PANEL
# ============================================================
def animated_menu_panel(title: str, items: list, border_style: str = None):
    if border_style is None:
        border_style = SETTINGS.color("border", "bright_blue")
    if not SETTINGS.get("menu_animation", True):
        menu_panel(title, items, border_style)
        return
    console.print()
    console.print(f"[bold {border_style}]╔{'═' * 50}╗[/bold {border_style}]")
    console.print(f"[bold {border_style}]║[/bold {border_style}]{' ' * 13}[bold {SETTINGS.color('primary')}]{title}[/bold {SETTINGS.color('primary')}]{' ' * (13 + max(0, 24 - len(title)))}[bold {border_style}]║[/bold {border_style}]")
    console.print(f"[bold {border_style}]╚{'═' * 50}╝[/bold {border_style}]")
    time.sleep(0.1)
    for label, desc in items:
        console.print(f"  [bold {SETTINGS.color('accent')}]{label}[/bold {SETTINGS.color('accent')}]  {desc}")
        time.sleep(0.02)
    console.print()

# ============================================================
#  INVENTORY SEARCH
# ============================================================
def search_inventory(stats: Dict[str, Any], query: str) -> List[Dict[str, Any]]:
    results = []
    query_lower = query.lower()
    for item in stats.get("Backpack", []):
        name = item.get("Name", "").lower()
        cls = item.get("Class", "").lower()
        if query_lower in name or query_lower in cls:
            results.append(item)
    return results

def count_item_in_backpack(stats: Dict[str, Any], item_name: str) -> int:
    count = 0
    for item in stats.get("Backpack", []):
        if item.get("Name") == item_name:
            count += 1
    return count

def remove_items_from_backpack(stats: Dict[str, Any], item_name: str, count: int = 1) -> int:
    removed = 0
    backpack = stats.get("Backpack", [])
    new_backpack = []
    for item in backpack:
        if item.get("Name") == item_name and removed < count:
            removed += 1
        else:
            new_backpack.append(item)
    stats["Backpack"] = new_backpack
    return removed

# ============================================================
#  TRADE/VALUE CALCULATION
# ============================================================
def calculate_item_value(item: Dict[str, Any], quality: str = "standard") -> int:
    base_cost = item.get("Cost", 100)
    q = QUALITY_SUFFIXES.get(quality, QUALITY_SUFFIXES["standard"])
    return int(base_cost * q.get("cost_mod", 1.0))

def calculate_sell_value(item: Dict[str, Any], quality: str = "standard") -> int:
    base = calculate_item_value(item, quality)
    return int(base * 0.5)

