def get_enchant_cost(enchant_name: str, level: int = 1) -> Dict[str, int]:
    enchant_data = ENCHANT_COST_TABLE.get(enchant_name, {})
    costs = enchant_data.get(level, {})
    if not costs:
        level = 1
        costs = enchant_data.get(level, {"Prisms": 1, "Gold": 5000})
    return costs

# ============================================================
#  PLAYER STAT MODIFIERS
# ============================================================
def get_player_stat_total(stats: Dict[str, Any], stat_key: str) -> int:
    total = stats.get(stat_key, 0)
    if stat_key == "STR" and "Weapon" in stats:
        total += stats["Weapon"].get("ATK", 0) * 10
    if stat_key == "DEF":
        for slot in ["Helmet", "Chestplate", "Leggings", "Boots", "Left Hand"]:
            item = stats.get(slot, {})
            total += item.get("DEF", 0) * 10
    if stat_key == "SP":
        for slot in ["Weapon", "Helmet", "Chestplate", "Leggings", "Boots", "Left Hand"]:
            item = stats.get(slot, {})
            total += item.get("SP", 0) * 20
    if stat_key == "Crit" and "Weapon" in stats:
        total += stats["Weapon"].get("Crit", 0) * 10
    return int(total)

