# ============================================================
#  ITEM COMPARISON TOOLTIP
# ============================================================
def item_tooltip(item: Dict[str, Any]) -> str:
    parts = [f"[bold {SETTINGS.color('accent')}]{item.get('Name', 'Unknown')}[/bold {SETTINGS.color('accent')}]"]
    cls = item.get("Class", "")
    if cls:
        parts.append(f"[dim]({cls})[/dim]")
    for key in ["ATK", "DEF", "SP", "Crit", "Effect", "Chance", "Tier"]:
        if key in item:
            color = {"ATK": SETTINGS.color("danger"), "DEF": SETTINGS.color("secondary"), "SP": SETTINGS.color("success"), "Crit": SETTINGS.color("warning"), "Effect": SETTINGS.color("magic"), "Chance": SETTINGS.color("info")}.get(key, SETTINGS.color("text"))
            parts.append(f"  [{color}]{key}: {item[key]}[/{color}]")
    if "Cost" in item:
        parts.append(f"  [bold {SETTINGS.color('gold')}]Cost: {item['Cost']}[/bold {SETTINGS.color('gold')}]")
    return "\n".join(parts)

