# ============================================================
#  UI ANIMATION HELPERS - CONTINUED
# ============================================================
def fade_in_text(text: str, color: str = None, steps: int = 5):
    if color is None:
        color = SETTINGS.color("primary", "bright_blue")
    if not SETTINGS.get("menu_animation", True):
        console.print(f"[bold {color}]{text}[/bold {color}]")
        return
    for i in range(1, steps + 1):
        alpha = i / steps
        if i < steps:
            console.print(f"[dim {color}]{text}[/dim {color}]", end="\r")
        else:
            console.print(f"[bold {color}]{text}[/bold {color}]")
        time.sleep(0.05 * alpha)

def type_title(text: str, delay: float = 0.05):
    chars = list(str(text))
    for i in range(len(chars)):
        line = "".join(chars[:i + 1])
        console.print(f"[bold {SETTINGS.color('accent')}]{line}[/bold {SETTINGS.color('accent')}]", end="\r")
        time.sleep(delay)
    console.print()

def pulse_effect(text: str, color: str = None, times: int = 3):
    if color is None:
        color = SETTINGS.color("primary", "bright_blue")
    for _ in range(times):
        console.print(f"[bold {color}]{text}[/bold {color}]", end="\r")
        time.sleep(0.1)
        console.print(f"[dim {color}]{text}[/dim {color}]", end="\r")
        time.sleep(0.1)
    console.print(f"[bold {color}]{text}[/bold {color}]")

def marquee_text(text: str, width: int = 40, speed: float = 0.05):
    text = str(text)
    padded = text + "   " * 5
    for i in range(len(padded) - width + 1):
        segment = padded[i:i + width]
        console.print(f"[dim]{segment}[/dim]", end="\r")
        time.sleep(speed)
    console.print()

