# ============================================================
#  REVIEW/RECAP GENERATOR
# ============================================================
def generate_session_recap(stats: Dict[str, Any]) -> str:
    name = stats.get("Name", "Adventurer")
    lvl = stats.get("Lvl", 1)
    title = get_player_title(lvl)
    gold = stats.get("Gold", 0)
    hp = stats.get("HP", 0)
    max_hp = stats.get("Max HP", 1000)
    zone_count = len([k for k in stats.get("zones_visited", set()) if k])
    adventures = stats.get("adventures_done", 0)
    arena_wins = stats.get("arena_wins", 0)
    bosses = stats.get("bosses_defeated", 0)
    parts = [
        f"[bold {SETTINGS.color('primary')}]═══ SESSION RECAP ═══[/bold {SETTINGS.color('primary')}]",
        f"[bold]{name}[/bold] the [bold {SETTINGS.color('accent')}]{title}[/bold {SETTINGS.color('accent')}]",
        f"[bold]Level:[/bold] {lvl}",
        f"[bold {SETTINGS.color('hp_high')}]HP:[/bold {SETTINGS.color('hp_high')}] {hp}/{max_hp}",
        f"[bold {SETTINGS.color('gold')}]Gold:[/bold {SETTINGS.color('gold')}] {gold}",
        f"[bold]Zones Explored:[/bold] {zone_count}",
        f"[bold]Adventures:[/bold] {adventures} | [bold]Arena Wins:[/bold] {arena_wins} | [bold]Bosses Defeated:[/bold] {bosses}",
    ]
    return "\n".join(parts)

