STATUS_COMBOS = {
    "burning_frozen": {"name": "Steam Explosion", "damage": 0.15, "desc": "Fire and ice collide! A massive steam explosion!",
                       "condition": lambda effects: "burning" in effects and "frozen" in effects},
    "poisoned_bleeding": {"name": "Hemotoxin", "damage": 0.12, "desc": "Poison mixes with blood! Damage intensifies!",
                          "condition": lambda effects: "poisoned" in effects and "bleeding" in effects},
    "shielded_regenerating": {"name": "Fortress", "heal": 0.08, "desc": "Defense and regeneration amplify each other!",
                              "condition": lambda effects: "shielded" in effects and "regenerating" in effects},
    "enraged_burning": {"name": "Volcanic Fury", "damage": 0.2, "atk_boost": 2.0, "desc": "Rage and fire combine into a devastating inferno!",
                        "condition": lambda effects: "enraged" in effects and "burning" in effects},
}

def check_status_combos(target: Dict[str, Any]) -> List[str]:
    messages = []
    effects = target.get("status_effects", {})
    effect_keys = set(effects.keys())
    for combo_key, combo in STATUS_COMBOS.items():
        if combo.get("condition", lambda _: False)(effect_keys):
            dmg = combo.get("damage", 0)
            heal = combo.get("heal", 0)
            name = combo.get("name", "Combo")
            desc = combo.get("desc", "")
            if dmg > 0:
                dmg_amount = int(target.get("HP", 0) * dmg)
                target["HP"] = max(0, target.get("HP", 0) - dmg_amount)
                messages.append(f"⚡ {name}: {desc} (-{dmg_amount} HP)")
            if heal > 0:
                heal_amount = int(target.get("Max HP", 1000) * heal)
                target["HP"] = min(target.get("Max HP", 1000), target.get("HP", 0) + heal_amount)
                messages.append(f"💚 {name}: {desc} (+{heal_amount} HP)")
    return messages

