def get_attack_style(weapon_name: str) -> str:
    wlower = weapon_name.lower()
    for wtype, styles in WEAPON_ATTACK_STYLES.items():
        if wtype in wlower:
            return random.choice(styles)
    return random.choice(WEAPON_ATTACK_STYLES["sword"] + WEAPON_ATTACK_STYLES["axe"] + WEAPON_ATTACK_STYLES["dagger"])

