# ============================================================
#  FINAL FUNCTIONS SET
# ============================================================
def roll_damage_range(base_dmg: float, variance: float = 0.2) -> int:
    low = int(base_dmg * (1 - variance))
    high = int(base_dmg * (1 + variance))
    return random.randint(low, high)

def calculate_crit_damage(base_dmg: int, crit_chance: float) -> Tuple[int, bool]:
    is_crit = random.random() < (crit_chance / 100)
    if is_crit:
        return int(base_dmg * 2.0), True
    return base_dmg, False

def calculate_block_chance(block_value: float) -> bool:
    return random.random() < (block_value / 100)

def calculate_dodge_chance(sp_value: float) -> bool:
    dodge_chance = sp_value * 0.5
    return random.random() < (dodge_chance / 100)

def format_gold(amount: int) -> str:
    if amount >= 1000000:
        return f"{amount / 1000000:.1f}M"
    elif amount >= 1000:
        return f"{amount / 1000:.1f}K"
    return str(amount)

def format_time(seconds: int) -> str:
    hours = seconds // 3600
    minutes = (seconds % 3600) // 60
    secs = seconds % 60
    if hours > 0:
        return f"{hours}h {minutes}m {secs}s"
    elif minutes > 0:
        return f"{minutes}m {secs}s"
    return f"{secs}s"

def clamp(value: int, min_val: int, max_val: int) -> int:
    return max(min_val, min(max_val, value))

def calculate_level_for_exp(exp: int) -> int:
    level = 1
    required = 20
    while exp >= required:
        exp -= required
        level += 1
        required += 20
    return level

def calculate_exp_for_level(level: int) -> int:
    total = 0
    required = 20
    for _ in range(1, level):
        total += required
        required += 20
    return total

