MARKET_PRICES = {
    "Iron Ingot": {"base": 200, "volatility": 0.3},
    "Steel Ingot": {"base": 500, "volatility": 0.25},
    "Crystal Shard": {"base": 1000, "volatility": 0.4},
    "Magic Essence": {"base": 2000, "volatility": 0.5},
    "Diamond": {"base": 10000, "volatility": 0.2},
    "Dragonite": {"base": 100000, "volatility": 0.3},
    "Herb": {"base": 50, "volatility": 0.2},
    "Leather": {"base": 100, "volatility": 0.15},
}

def get_market_price(item_name: str) -> int:
    data = MARKET_PRICES.get(item_name)
    if not data:
        return None
    base = data["base"]
    volatility = data["volatility"]
    fluctuation = random.uniform(-volatility, volatility)
    return int(base * (1 + fluctuation))

def get_market_price_display(item_name: str) -> str:
    price = get_market_price(item_name)
    if price is None:
        return "Unknown"
    return f"{price} gold"

