def check_armor_set_bonuses(stats: Dict[str, Any]) -> List[str]:
    messages = []
    equipped = {}
    for slot in ["Helmet", "Chestplate", "Leggings", "Boots"]:
        item = stats.get(slot, {})
        name = item.get("Name", "")
        if name:
            equipped[slot] = name
    for set_key, set_data in ARMOR_SETS.items():
        pieces = set_data["pieces"]
        matching = 0
        for slot, equip_name in equipped.items():
            if equip_name in pieces:
                matching += 1
        if matching >= 2:
            bonus_2 = set_data.get("bonus_2", {})
            for stat, val in bonus_2.items():
                if stat == "HP":
                    stats["Max HP"] = stats.get("Max HP", 1000) + val
                elif stat == "ATK":
                    stats["STR"] = stats.get("STR", 0) + val
                elif stat == "DEF":
                    stats["DEF"] = stats.get("DEF", 0) + val
                elif stat == "SP":
                    stats["SP"] = stats.get("SP", 0) + val
                elif stat == "Crit":
                    stats["Crit"] = stats.get("Crit", 0) + val
            if matching >= 4:
                bonus_4 = set_data.get("bonus_4", {})
                for stat, val in bonus_4.items():
                    if stat == "HP":
                        stats["Max HP"] = stats.get("Max HP", 1000) + val
                    elif stat == "ATK":
                        stats["STR"] = stats.get("STR", 0) + val
                    elif stat == "DEF":
                        stats["DEF"] = stats.get("DEF", 0) + val
                    elif stat == "SP":
                        stats["SP"] = stats.get("SP", 0) + val
                    elif stat == "Crit":
                        stats["Crit"] = stats.get("Crit", 0) + val
                name = set_data["name"]
                desc = set_data["desc"]
                messages.append(f"✦ {name} (4-piece): {desc}")
            else:
                name = set_data["name"]
                messages.append(f"✦ {name} (2-piece): Partial bonus active")
    return messages


