def generate_dungeon(theme_key: str, player_level: int) -> Dict[str, Any]:
    theme = DUNGEON_THEMES.get(theme_key, DUNGEON_THEMES["goblin"])
    num_floors = random.randint(*theme["floors"])
    floors = []
    for i in range(num_floors):
        floor = generate_dungeon_floor(i + 1)
        floors.append(floor)
    return {
        "name": theme["name"],
        "desc": theme["desc"],
        "floors": floors,
        "enemies": theme["enemies"],
        "boss": theme["boss"],
        "loot_tier": theme["loot_tier"],
        "theme_key": theme_key,
        "num_floors": num_floors,
    }

def describe_dungeon(dungeon: Dict[str, Any]) -> str:
    name = dungeon.get("name", "Unknown Dungeon")
    desc = dungeon.get("desc", "")
    floors = dungeon.get("num_floors", 0)
    boss = dungeon.get("boss", "Unknown")
    return f"[bold {SETTINGS.color('accent')}]{name}[/bold {SETTINGS.color('accent')}]\n  {desc}\n  [bold]Floors:[/bold] {floors} | [bold {SETTINGS.color('danger')}]Boss: {boss}[/bold {SETTINGS.color('danger')}]"

