def get_player_stat_summary(stats: Dict[str, Any]) -> List[str]:
    lines = []
    lines.append(f"[bold {SETTINGS.color('primary')}]═══ {stats.get('Name', 'Adventurer')} ═══[/bold {SETTINGS.color('primary')}]")
    lines.append(f"[bold]Level:[/bold] {stats.get('Lvl', 1)}")
    lines.append(f"[bold]Title:[/bold] {get_player_title(stats.get('Lvl', 1))}")
    lines.append(f"[bold {SETTINGS.color('success')}]HP:[/bold {SETTINGS.color('success')}] {stats.get('HP', 0)} / {stats.get('Max HP', 1000)}")
    lines.append(f"[bold {SETTINGS.color('danger')}]ATK:[/bold {SETTINGS.color('danger')}] {stats.get('STR', 0)}")
    lines.append(f"[bold {SETTINGS.color('secondary')}]DEF:[/bold {SETTINGS.color('secondary')}] {stats.get('DEF', 0)}")
    lines.append(f"[bold {SETTINGS.color('info')}]SPD:[/bold {SETTINGS.color('info')}] {stats.get('SP', 0)}")
    lines.append(f"[bold {SETTINGS.color('warning')}]CRIT:[/bold {SETTINGS.color('warning')}] {stats.get('Crit', 0)}%")
    lines.append(f"[bold {SETTINGS.color('gold')}]Gold:[/bold {SETTINGS.color('gold')}] {stats.get('Gold', 0)}")
    lines.append(f"[bold]Reputation:[/bold] {stats.get('Reputation', 0)}")
    lines.append(f"[bold]EXP:[/bold] {stats.get('EXP', 0)} / {stats.get('Max EXP', 20)}")
    lines.append(f"[bold]Rank:[/bold] {stats.get('Rank', 10000)}")
    return lines

# ============================================================
#  CHARACTER SHEET GENERATOR
# ============================================================
def generate_character_sheet(stats: Dict[str, Any]) -> str:
    lines = get_player_stat_summary(stats)
    lines.append("")
    lines.append("[bold]Equipment:[/bold]")
    for slot in ["Weapon", "Left Hand", "Helmet", "Chestplate", "Leggings", "Boots"]:
        item = stats.get(slot, {})
        name = item.get("Name", "Empty")
        lines.append(f"  [bold]{slot}:[/bold] {name}")
    lines.append("")
    lines.append(f"[bold]Backpack:[/bold] {len(stats.get('Backpack', []))} items")
    bg_count = len(stats.get("Backpack", []))
    if bg_count > 0:
        classes = {}
        for item in stats.get("Backpack", []):
            cls = item.get("Class", "Unknown")
            classes[cls] = classes.get(cls, 0) + 1
        for cls, count in sorted(classes.items()):
            lines.append(f"  [dim]{cls}: {count}[/dim]")
    lines.append("")
    achievements = stats.get("achievements", {})
    unlocked = sum(1 for v in achievements.values() if v)
    if unlocked > 0:
        lines.append(f"[bold]Achievements:[/bold] {unlocked} unlocked")
    return "\n".join(lines)

# ============================================================
#  INVENTORY SORT
# ============================================================
SORT_OPTIONS = {
    "name": lambda item: item.get("Name", ""),
    "class": lambda item: item.get("Class", ""),
    "cost_asc": lambda item: item.get("Cost", 0),
    "cost_desc": lambda item: -item.get("Cost", 0),
    "atk": lambda item: -item.get("ATK", 0),
    "def": lambda item: -item.get("DEF", 0),
}

def sort_inventory(stats: Dict[str, Any], sort_key: str = "name") -> None:
    sorter = SORT_OPTIONS.get(sort_key, SORT_OPTIONS["name"])
    stats["Backpack"] = sorted(stats.get("Backpack", []), key=sorter)

def display_sorted_inventory(stats: Dict[str, Any], sort_key: str = "name") -> None:
    sort_inventory(stats, sort_key)
    if not stats.get("Backpack"):
        console.print("  [dim italic]Backpack is empty[/dim italic]")
        return
    section(f"SORTED BY: {sort_key.upper()}")
    for item in stats["Backpack"]:
        name = item.get("Name", "Unknown")
        cls = item.get("Class", "")
        cost = item.get("Cost", 0)
        console.print(f"  [bold {SETTINGS.color('accent')}]{name}[/bold {SETTINGS.color('accent')}] [dim]({cls}[/dim]) [bold {SETTINGS.color('gold')}]{cost}G[/bold {SETTINGS.color('gold')}]")

