def roll_extra_encounter() -> Dict[str, Any]:
    pool = []
    for enc in ENCOUNTER_EXTRA:
        pool.extend([enc] * enc.get("weight", 5))
    return random.choice(pool) if pool else ENCOUNTER_EXTRA[0]

def process_extra_encounter(stats: Dict[str, Any], encounter: Dict[str, Any]) -> None:
    if encounter is None:
        return
    name = encounter.get("name", "Encounter")
    desc = encounter.get("desc", "")
    enc_type = encounter.get("type", "")
    screen_title(f"📍 {name}")
    dialogue(desc, "narrator", 0.03)
    time.sleep(0.2)
    if enc_type == "trade":
        event("The merchant shows you their wares.", "info")
        cash = random.randint(100, 1000)
        stats["Gold"] = stats.get("Gold", 0) + cash
        event(f"You make a small profit: +{cash} gold!", "gold")
    elif enc_type == "companion":
        comp_type = encounter.get("companion_type", "wolf")
        if "companion" not in stats:
            stats["companion"] = comp_type
            comp = COMPANION_TYPES.get(comp_type, {})
            event(f"{comp.get('name', comp_type)} joins you!", "success")
    elif enc_type == "shrine":
        if random.random() < encounter.get("blessing_chance", 0.5):
            stats["HP"] = min(stats.get("Max HP", 1000), stats.get("HP", 0) + 500)
            stats["_blessing"] = stats.get("_blessing", 0) + 1
            event("A blessing from the gods! +500 HP!", "heal")
        else:
            event("The altar remains silent.", "info")
    elif enc_type == "choice":
        options = encounter.get("options", ["Yes", "No"])
        for i, opt in enumerate(options, 1):
            console.print(f"  [bold cyan]{i}.[/bold cyan] {opt}")
        pick = int_prompt("What do you do? ")
        if pick == 1:
            event("Your choice has consequences...", "warning")
            stats["Reputation"] = stats.get("Reputation", 0) + 5
        elif pick == 2:
            event("You walk away.", "info")
        else:
            event("You take the unexpected path.", "magic")
    elif enc_type == "portal":
        event("You step through the portal and find yourself somewhere new!", "magic")
        gold = random.randint(500, 5000)
        stats["Gold"] = stats.get("Gold", 0) + gold
        event(f"Gained {gold} gold from the experience!", "gold")
    elif enc_type == "fey":
        event("The fey creatures dance around you, filling you with energy!", "magic")
        stats["Max HP"] = stats.get("Max HP", 1000) + 50
        event("+50 Max HP!", "heal")
    elif enc_type == "rescue":
        event("You help the survivors. They reward you generously!", "loot")
        reward = random.randint(1000, 3000)
        stats["Gold"] = stats.get("Gold", 0) + reward
        stats["Reputation"] = stats.get("Reputation", 0) + 3
        event(f"+{reward} gold and +3 reputation!", "gold")
    elif enc_type == "mystery":
        event("The cave's song fills you with wonder. You gain insight.", "info")
        grant_exp(stats, 100)
    time.sleep(0.3)
    clear()

