def get_companion_battle_stats(stats: Dict[str, Any]) -> Dict[str, Any]:
    comp_type = stats.get("companion", None)
    if not comp_type:
        return None
    comp_data = COMPANION_TYPES.get(comp_type, None)
    if not comp_data:
        return None
    return {
        "Name": comp_data["name"],
        "HP": comp_data["hp"],
        "ATK": comp_data["atk"],
        "DEF": comp_data["def"],
        "SP": 20,
        "Crit": 5,
    }

