def healing_spring_event(stats: Dict[str, Any]) -> None:
    desc = random.choice(HEALING_SPRING_DESCRIPTIONS)
    dialogue(desc, "narrator", 0.03)
    heal_pct = random.uniform(0.3, 0.6)
    heal = int(stats.get("Max HP", 1000) * heal_pct)
    stats["HP"] = min(stats.get("Max HP", 1000), stats.get("HP", 0) + heal)
    event(f"Restored {heal} HP by the spring!", "heal")
    if random.random() < 0.2:
        stats["Max HP"] = stats.get("Max HP", 1000) + 10
        event("The spring's magic permanently increased your Max HP by 10!", "levelup")
    time.sleep(0.5)
    clear()

