# ============================================================
#  WORLD TIME SYSTEM
# ============================================================
TIME_OF_DAY = ["Dawn", "Morning", "Midday", "Afternoon", "Dusk", "Night", "Midnight"]
DAY_PHASES = {
    "Dawn": {"desc": "The first light of day breaks over the horizon.", "hp_regen": 0.05, "mood": "hopeful"},
    "Morning": {"desc": "The world awakens to a new day.", "hp_regen": 0.02, "mood": "energetic"},
    "Midday": {"desc": "The sun stands high and bright.", "hp_regen": 0.0, "mood": "alert"},
    "Afternoon": {"desc": "The day begins to wind down.", "hp_regen": 0.01, "mood": "calm"},
    "Dusk": {"desc": "The sky paints itself in shades of orange and purple.", "hp_regen": 0.03, "mood": "reflective"},
    "Night": {"desc": "Stars blanket the dark sky.", "hp_regen": 0.04, "mood": "mysterious"},
    "Midnight": {"desc": "The witching hour. Magic is at its peak.", "hp_regen": 0.08, "mood": "magical"},
}

def get_time_of_day() -> str:
    hour = random.randint(0, 23)
    if hour < 6:
        return "Night"
    elif hour < 7:
        return "Dawn"
    elif hour < 12:
        return "Morning"
    elif hour < 13:
        return "Midday"
    elif hour < 17:
        return "Afternoon"
    elif hour < 19:
        return "Dusk"
    elif hour < 22:
        return "Night"
    else:
        return "Midnight"

def describe_time_of_day(time_str: str = None) -> str:
    if time_str is None:
        time_str = get_time_of_day()
    phase = DAY_PHASES.get(time_str, DAY_PHASES["Morning"])
    return f"[bold {SETTINGS.color('accent')}]{time_str}[/bold {SETTINGS.color('accent')}] — [dim]{phase['desc']}[/dim]"

def apply_time_regen(stats: Dict[str, Any], time_str: str = None) -> None:
    if time_str is None:
        time_str = get_time_of_day()
    phase = DAY_PHASES.get(time_str, DAY_PHASES["Morning"])
    regen = phase.get("hp_regen", 0)
    if regen > 0 and stats.get("HP", 0) < stats.get("Max HP", 1000):
        heal = int(stats.get("Max HP", 1000) * regen)
        stats["HP"] = min(stats.get("Max HP", 1000), stats.get("HP", 0) + heal)
        if heal > 0:
            event(f"The {time_str.lower()} restores {heal} HP.", "heal")

