# ============================================================
#  TOOLTIP AND UI HELPERS
# ============================================================
def colored_stat(label: str, value, color_key: str = "text") -> str:
    c = SETTINGS.color(color_key, "white")
    return f"[bold {c}]{label}: {value}[/bold {c}]"

def stat_block(items: List[Tuple[str, Any, str]]) -> str:
    parts = []
    for label, value, color_key in items:
        parts.append(colored_stat(label, value, color_key))
    return " | ".join(parts)

def item_summary(item: Dict[str, Any]) -> str:
    parts = [f"[bold {SETTINGS.color('accent')}]{item.get('Name', 'Item')}[/bold {SETTINGS.color('accent')}]"]
    cls = item.get("Class", "")
    if cls:
        parts.append(f"[dim]({cls})[/dim]")
    cost = item.get("Cost", 0)
    if cost:
        parts.append(f"[bold {SETTINGS.color('gold')}]{cost}G[/bold {SETTINGS.color('gold')}]")
    return " ".join(parts)

def player_title_line(stats: Dict[str, Any]) -> str:
    name = stats.get("Name", "Adventurer")
    lvl = stats.get("Lvl", 1)
    title = get_player_title(lvl)
    hp = stats.get("HP", 0)
    max_hp = stats.get("Max HP", 1000)
    gold = stats.get("Gold", 0)
    return f"[bold {SETTINGS.color('primary')}]{name}[/bold {SETTINGS.color('primary')}] the {title} | [bold {SETTINGS.color('success')}]HP: {hp}/{max_hp}[/bold {SETTINGS.color('success')}] | [bold {SETTINGS.color('gold')}]{format_gold(gold)}G[/bold {SETTINGS.color('gold')}]"

