def get_comprehensive_zone_desc(zone_key: str) -> str:
    data = ZONE_COMPREHENSIVE_DESC.get(zone_key, {})
    terrain = data.get("terrain", "Unknown")
    inhabitants = data.get("inhabitants", "Unknown")
    points = data.get("points_of_interest", [])
    resources = data.get("resources", [])
    result = [
        f"[bold]Terrain:[/bold] {terrain}",
        f"[bold]Inhabitants:[/bold] {inhabitants}",
        f"[bold]Points of Interest:[/bold]",
    ]
    for poi in points:
        result.append(f"  • {poi}")
    result.append(f"[bold]Known Resources:[/bold]")
    for res in resources:
        result.append(f"  • {res}")
    return "\n".join(result)

