def ultimate_stat_display(stats: Dict[str, Any]) -> None:
    total_items = len(stats.get("Backpack", []))
    equipment_slots = ["Weapon", "Left Hand", "Helmet", "Chestplate", "Leggings", "Boots"]
    equipped_count = sum(1 for slot in equipment_slots if stats.get(slot, {}).get("Name", ""))
    total_gold = stats.get("Gold", 0)
    total_level = stats.get("Lvl", 1)
    total_exp = stats.get("EXP", 0)
    max_exp = stats.get("Max EXP", 20)
    adventures = stats.get("adventures_done", 0)
    arena_wins = stats.get("arena_wins", 0)
    bosses = stats.get("bosses_defeated", 0)
    reputation = stats.get("Reputation", 0)
    rep_title = get_reputation_title(reputation)
    rank = stats.get("Rank", 10000)
    rank_title = get_rank_title(rank)
    achievements = sum(1 for v in stats.get("achievements", {}).values() if v)
    screen_title("📊 ULTIMATE STATISTICS", "Every detail of your journey")
    console.print(f"  [bold]Character:[/bold] {stats.get('Name', 'Unknown')}")
    console.print(f"  [bold]Level:[/bold] {total_level}  [bold]EXP:[/bold] {total_exp}/{max_exp}")
    console.print(f"  [bold]Rank:[/bold] {rank} ({rank_title})")
    console.print(f"  [bold {SETTINGS.color('gold')}]Gold:[/bold {SETTINGS.color('gold')}] {format_gold(total_gold)}")
    console.print(f"  [bold]Reputation:[/bold] {reputation} ({rep_title})")
    console.print(f"  [bold]Equipment:[/bold] {equipped_count}/6 slots filled")
    console.print(f"  [bold]Inventory:[/bold] {total_items} items")
    console.print(f"  [bold]Adventures:[/bold] {adventures}")
    console.print(f"  [bold]Arena Wins:[/bold] {arena_wins}")
    console.print(f"  [bold]Bosses Defeated:[/bold] {bosses}")
    console.print(f"  [bold]Achievements:[/bold] {achievements} unlocked")
    total_hp = stats.get("HP", 0)
    max_hp = stats.get("Max HP", 1000)
    atk = stats.get("STR", 0)
    defe = stats.get("DEF", 0)
    sp = stats.get("SP", 0)
    crit = stats.get("Crit", 0)
    console.print(f"  [bold {SETTINGS.color('hp_high')}]HP:[/bold {SETTINGS.color('hp_high')}] {total_hp}/{max_hp}")
    console.print(f"  [bold {SETTINGS.color('danger')}]ATK:[/bold {SETTINGS.color('danger')}] {atk}")
    console.print(f"  [bold {SETTINGS.color('secondary')}]DEF:[/bold {SETTINGS.color('secondary')}] {defe}")
    console.print(f"  [bold {SETTINGS.color('info')}]SPD:[/bold {SETTINGS.color('info')}] {sp}")
    console.print(f"  [bold {SETTINGS.color('warning')}]CRIT:[/bold {SETTINGS.color('warning')}] {crit}%")
    gold_list = ["Gold", "Diamond", "Dragonite", "Celestium Prism"]
    for curr in gold_list:
        val = stats.get(curr, 0)
        if val > 0:
            console.print(f"  [bold]  {curr}:[/bold] {val}")
    console.input("[dim]Press Enter to continue...[/dim]")
    clear()

# ============================================================
#  INVENTORY MANAGER
# ============================================================
def inventory_manager(stats: Dict[str, Any]) -> None:
    while True:
        bp = stats.get("Backpack", [])
        screen_title("🎒 INVENTORY", f"{len(bp)} items")
        if bp:
            for i, item in enumerate(bp[:20], 1):
                name = item.get("Name", "Unknown")
                cls = item.get("Class", "")
                cost = item.get("Cost", 0)
                console.print(f"  [bold cyan]{i}.[/bold cyan] {item_summary(item)}")
            if len(bp) > 20:
                console.print(f"  ... and {len(bp) - 20} more items")
        else:
            console.print("  [dim italic]Your backpack is empty.[/dim italic]")
        console.print()
        console.print("  [bold cyan]1.[/bold cyan] Use Item")
        console.print("  [bold cyan]2.[/bold cyan] Sort Items")
        console.print("  [bold cyan]3.[/bold cyan] Search Items")
        console.print("  [bold cyan]4.[/bold cyan] Discard Item")
        console.print("  [bold cyan]5.[/bold cyan] Exit Inventory")
        console.print()
        choice = int_prompt("Choose: ")
        clear()
        if choice == 1:
            item_name = console.input("Enter item name to use: ")
            use_item(stats, item_name)
            time.sleep(0.5)
            clear()
        elif choice == 2:
            sort_key = console.input("Sort by (name/class/cost/atk/def): ").lower()
            display_sorted_inventory(stats, sort_key)
            console.input("[dim]Press Enter to continue...[/dim]")
            clear()
        elif choice == 3:
            query = console.input("Search: ")
            results = search_inventory(stats, query)
            if results:
                section("SEARCH RESULTS")
                for item in results:
                    console.print(f"  {item_summary(item)}")
            else:
                event("No items found.", "info")
            console.input("[dim]Press Enter to continue...[/dim]")
            clear()
        elif choice == 4:
            item_name = console.input("Enter item name to discard: ")
            count = int_prompt("How many? ", default=1)
            removed = remove_items_from_backpack(stats, item_name, count)
            if removed > 0:
                event(f"Discarded {removed}x {item_name}.", "warning")
            else:
                event("Item not found.", "warning")
            time.sleep(0.5)
            clear()
        elif choice == 5:
            break


