def apply_mood_effect(stats: Dict[str, Any], mood: str) -> None:
    if mood == "hopeful":
        heal = int(stats.get("Max HP", 1000) * 0.02)
        stats["HP"] = min(stats.get("Max HP", 1000), stats.get("HP", 0) + heal)
    elif mood == "determined":
        stats["_mood_atk"] = stats.get("_mood_atk", 0) + 5
    elif mood == "fearful":
        stats["_mood_def"] = stats.get("_mood_def", 0) - 5
    elif mood == "triumphant":
        grant_exp(stats, 25)

