def apply_background(stats: Dict[str, Any], bg_key: str) -> None:
    bg = random.choice(BACKGROUNDS)
    name = bg["name"]
    desc = bg["desc"]
    bonuses = bg.get("stat_bonus", {})
    dialogue(f"Background: {name}", "narrator", 0.03)
    console.print(f"  [dim]{desc}[/dim]")
    event(f"Background applied: {name}", "info")
    for stat, val in bonuses.items():
        if stat == "Gold":
            stats["Gold"] = stats.get("Gold", 0) + val
        elif stat == "HP":
            stats["Max HP"] = stats.get("Max HP", 1000) + val
            stats["HP"] = stats.get("HP", 0) + val
        else:
            stats[stat] = stats.get(stat, 0) + val
        event(f"+{val} {stat}!", "levelup")
    time.sleep(0.5)
    clear()

