#  SELLING PRICE RANGES
# ============================================================
SELLING_PRICE_RANGES = {
    "cracked": (0.2, 0.4),
    "worn": (0.3, 0.5),
    "standard": (0.4, 0.6),
    "polished": (0.5, 0.7),
    "superior": (0.6, 0.75),
    "masterwork": (0.65, 0.8),
    "legendary": (0.7, 0.9),
    "ancient": (0.75, 0.95),
    "eldritch": (0.6, 0.85),
    "primordial": (0.8, 1.0),
    "aetherial": (0.85, 1.0),
    "mythic": (0.9, 1.0),
}

def calculate_sell_price_range(item: Dict[str, Any], quality: str = "standard") -> Tuple[int, int]:
    base = item.get("Cost", 100)
    range_data = SELLING_PRICE_RANGES.get(quality, (0.4, 0.6))
    low = int(base * range_data[0])
    high = int(base * range_data[1])
    return low, high

