TRADE_ROUTES = {
    "valdris_goldspire": {"name": "Valdris to Goldspire", "distance": 3, "danger": "Low", "profit_range": (500, 2000)},
    "goldspire_sapphire": {"name": "Goldspire to Sapphire Docks", "distance": 2, "danger": "Low", "profit_range": (300, 1500)},
    "sapphire_crimson": {"name": "Sapphire to Crimson Fields", "distance": 4, "danger": "Medium", "profit_range": (1000, 3000)},
    "crimson_rotfang": {"name": "Crimson Fields to Rotfang Depths", "distance": 5, "danger": "High", "profit_range": (2000, 5000)},
    "rotfang_crystal": {"name": "Rotfang to Crystal Peaks", "distance": 7, "danger": "Very High", "profit_range": (5000, 10000)},
}

def get_trade_route(route_key: str) -> Dict[str, Any]:
    return TRADE_ROUTES.get(route_key, TRADE_ROUTES["valdris_goldspire"])

def get_random_trade_route(min_safe: str = "Low") -> Dict[str, Any]:
    safe_levels = {"Low": 1, "Medium": 2, "High": 3, "Very High": 4}
    min_level = safe_levels.get(min_safe, 1)
    eligible = [(k, v) for k, v in TRADE_ROUTES.items() if safe_levels.get(v["danger"], 1) >= min_level]
    if not eligible:
        return TRADE_ROUTES["valdris_goldspire"]
    return random.choice(eligible)[1]

